    exp1: "錯誤とは、意思と表示が一致しない状態で行われた意思表示。2020年民法改正で「無効」から「取消」に変更された。①法律行為の目的・取引上の社会通念に照らして重要な錯誤、②表意者に重大な過失がないこと、が要件。動機の錯誤は相手方に動機を表示していた場合に取消可。",
