    exp1: "詐欺とは、相手方または第三者が欺罔行為によって表意者を錯誤に陥らせ、その錯誤に基づいて意思表示をさせること。取消可能。ただし第三者詐欺（相手方以外の第三者が詐欺を行った場合）は、相手方が詐欺の事実を知っていたまたは知り得た場合に限り取消可能。取消後は善意無過失の第三者に対抗不可。",
    exp2: "頻出論点は「第三者詐欺の取消条件」と「取消後の第三者保護」の2点だ。第三者詐欺（売主ではなく第三者が欺罔）の場合、取消には相手方の悪意または有過失が要件となる。取消の効果は遡及するが、取消前に善意無過失の第三者が登場すると対抗できなくなる。具体例：AがCの詐欺でBに土地を売り、BがCに売却した場合、BはCに悪意がある場合のみAは取消を主張できる。",
