    exp1: "代理とは、代理人が本人の名において（顕名）法律行為を行い、その効果が直接本人に帰属する制度。成立要件は①代理権の存在、②顕名（本人のためにすることを示す）、③代理行為。任意代理（委任による）と法定代理（法律による）がある。宅建では任意代理が中心。",
