    q: "次の状況に当てはまるのは？",
    choices: [{"text":"抵当権者は被担保債権の弁済を受けるため競売を申し立てることができる","correct":true},{"text":"競売代金は他の一般債権者と按分して分配される","correct":false,"hint":"抵当権者は優先弁済権を持ち、一般債権者に優先して配当を受ける"}],
    exp1: "抵当権の実行とは、被担保債権の弁済期が過ぎても弁済がない場合に、抵当不動産を競売（担保不動産競売）してその代金から優先弁済を受ける手続き。競売は裁判所を通じて行われる（任意売却と区別）。競落代金は登記順位に従って各抵当権者に配当され、余剰があれば後順位債権者・所有者へ。",
    exp2: "「抵当権実行と法定地上権（t034）」の論点が難問として頻出だ。また競売による買受人は所有権を取得し、抵当権は競売により消滅する（剰余主義）。賃借権が抵当権に後れて設定された場合、競売により賃借権は消滅するが、競売申立前から対抗力ある賃借権（登記または引渡あり）は競売後の買受人に対抗できる。短期賃貸借保護規定は2004年に廃止されており、2026年現在は存在しない。",
    exp3: "「強制競売」（確定判決等を債務名義とする競売）と「担保不動産競売」（抵当権実行）は別の手続きだ。抵当権実行は確定判決なしに競売申立できる（担保権の存在が証明できれば申立可能）のが最大のメリット。強制競売は先に裁判で勝訴判決を得てから申立しなければならない。どちらも競落代金の配分方法（配当）は同様のルールによる。\n\n**覚え方**\n抵当権実行は「判決なしに動ける強力な手段」。競売を申し立てて競落代金から優先弁済を受けるのが目的。",
