    exp1: "法定地上権とは、同一の所有者が土地と建物の両方を所有していた状態で、一方にのみ抵当権が設定された後に競売が行われ、土地と建物の所有者が別々になった場合に、建物のために法律上当然に成立する地上権（民法388条）。成立要件：①抵当権設定時に土地と建物が同一所有者、②土地または建物に抵当権が設定された、③競売により土地と建物の所有者が異なった。",
    exp2: "法定地上権の成立要件を一つずつ確認することが試験頻出だ。成立するケース：抵当権設定時に建物ありで土地建物が同一所有者→競売後に所有者分離→法定地上権成立。成立しないケース：①設定時に更地→法定地上権不成立（一括競売t035の問題となる）、②設定時に既に土地と建物の所有者が異なる→法定地上権不成立。建物が未登記でも設定時に建物が存在していれば法定地上権は成立する（判例）。地代は当事者の協議で決め、協議が整わなければ裁判所が決定する。",
    exp3: "「法定地上権」と「借地権（賃借権による）」を混同しない。法定地上権は競売をきっかけに法律上当然に発生する（契約不要・設定の意思表示不要）。借地権は当事者間の契約によって設定される（地主の同意が必要）。法定地上権の地代は協議または裁判所が決め、借地権の地代は契約で定める。\n\n**覚え方**\n法定地上権は「競売で引き裂かれたカップル（土地と建物）の最後の絆」。法律が「建物使えるよ」と地上権をプレゼントする。",
