    exp1: "一括競売とは、更地に抵当権設定後、設定者が建物を建築した場合に、土地の抵当権者が土地と建物を一括して競売できる制度（民法389条）。法定地上権が成立しないケース（設定時更地）で、建物を残したまま土地だけ競売すると利用価値が激減するため、一括競売を認めた。ただし建物の売却代金には優先弁済権は及ばない（土地代金のみ）。",
    exp2: "法定地上権との対比で出題される。整理すると：更地に抵当権設定→その後建物建築→競売＝一括競売可能・法定地上権不成立（設定時に建物なかったから）。土地建物同一所有時に土地または建物に抵当権設定→競売で土地建物所有者が分離＝法定地上権成立。この2パターンの場合分けを確実に押さえる。法定地上権が成立しない場面では一括競売という手段が代替として機能する。",
    exp3: "一括競売は抵当権者の「権利」であって義務ではない。土地だけを競売することも法的には可能だが、その場合買受人は建物の収去（取壊し）を建物所有者に求めることができない（建物にも権利があるため）。そのため実務上は一括競売を選択することがほとんどだ。建物代金部分には優先弁済権が及ばないという一括競売の限界も覚えておく。\n\n**覚え方**\n一括競売は「更地に建ててしまった時の救済策」。土地と建物をセットで売るが、建物代金はもらえない。",
