    exp1: "使用貸借とは、無償で物を貸し付け借主が使用収益した後に返還する契約（民法593条）。賃貸借と異なり無償のため保護が弱く、借地借家法は適用されない。対抗力もない（登記しても第三者に対抗不可）。存続期間の定めがない場合は使用収益の目的が終了したときに終了、または貸主はいつでも返還請求可（ただし一定の猶予が必要）。",
    exp2: "「賃貸借との比較」が頻出だ。使用貸借→無償・対抗力なし（引渡しても第三者に対抗不可）・借地借家法不適用・借主死亡で終了（民法599条）。賃貸借→有償・対抗力あり（引渡または登記）・借地借家法適用・相続される。特に「借主が死亡すると使用貸借は終了する」点は賃貸借と全く異なる重要ポイント。具体例：親が子に土地を無償で貸して家を建てさせたが、子が死亡した場合、孫には使用貸借の借主の地位は承継されない（使用貸借終了）。賃貸借なら相続人に承継される。",
    exp3: "「無償だから契約ではない」は誤り。使用貸借は立派な契約（2020年改正前は要物契約だったが、改正後は合意のみで成立する諾成契約に変更）。ただし無償のため借主保護が薄く、貸主はいつでも返還請求できる（ただし相手方に不利な時期は損害賠償が必要な場合がある）。\n\n**覚え方**\n使用貸借は「タダ借りは保護薄め」。対抗力なし・借主死亡で終了・借地借家法なし。賃料を払って初めてフル保護を受けられる。",
