    exp1: "原状回復とは、契約解除後または賃貸借終了後に目的物を元の状態に戻す義務。賃貸借における原状回復は「賃借人の故意・過失、善管注意義務違反による損傷」のみが賃借人負担。通常の使用収益による損耗（通常損耗）・経年変化は賃貸人負担（民法621条）。国土交通省のガイドラインが実務の基準となっている。",
    exp2: "「何が賃借人負担か・賃貸人負担か」の区分が試験頻出だ。賃借人負担→たばこのヤニ汚れ（故意・過失）・ペットによる傷・故意の穴あけ・冷蔵庫の下の黒ずみ（手入れ怠慢による汚損）。賃貸人負担→日焼けによる変色・経年劣化の畳・画鋲の小穴（通常使用の範囲）・結露によるカビ（ただし賃借人が換気を怠り悪化させた場合は賃借人負担になりうる）。国土交通省のガイドラインは2026年現在も実務の基準として使われている。",
