    exp1: "危険負担とは、双務契約で一方の債務が当事者双方の帰責事由なく履行不能になった場合、他方の反対給付債務をどう扱うかの問題。2020年民法改正で大きく変更。旧法→不動産売買は「債権者主義」（買主が危険負担）。改正後→「債務者主義」に統一（売主が危険負担）。買主は反対給付（代金支払）を拒絶できる。",
    exp2: "「改正前後の違い」が最重要だ。旧法（改正前）では不動産売買は「債権者主義」（買主が危険負担）→引渡前に建物が天災で滅失しても買主が代金を支払わなければならず、買主に酷だと批判された。2020年民法改正後（2026年現在）は「債務者主義」に統一→売主が履行不能なら買主は代金支払を拒絶できる。旧法の知識（債権者主義）で解答すると失点するため、「改正後は債務者主義」という方向性を確実に押さえる。",
    exp3: "債権者（買主）の帰責事由で滅失した場合は例外だ。この場合は買主は代金支払義務を負う（自分のせいで目的物が滅失したなら代金を払う義務がある）。たとえば引渡前に買主が内覧中に失火して建物が全焼した場合、買主の帰責事由なので買主は代金を支払わなければならない。\n\n**覚え方**\n危険負担は「改正後は売主が危険を負担する」。滅失したら売主が損をする（代金もらえない）のが原則。自分のせいで壊した側が損をするのは当然。",
