    exp1: "同時履行の抗弁権とは、双務契約の当事者が相手方から債務の履行（または履行の提供）を受けるまで、自己の債務の履行を拒絶できる権利（民法533条）。売買では代金支払と目的物引渡が同時履行の関係にある。この権利を行使している間は履行遅滞にならない（遅延損害金が発生しない）。",
    exp2: "宅建試験では「何と何が同時履行の関係にあるか」が頻出だ。同時履行の関係にある組合せ→売買代金支払と目的物引渡・所有権移転登記（判例）、解除後の原状回復義務相互（判例）、請負代金と目的物の引渡。同時履行の関係にないもの→敷金返還と明渡（判例：先に明け渡してから敷金返還を請求する順序。同時ではない）。また同時履行の抗弁権を行使している間は履行遅滞に陥らず、遅延損害金も発生しないことも押さえておく。",
