    exp1: "売買契約とは、当事者の一方（売主）が財産権を移転することを約し、相手方（買主）がその代金を支払うことを約する契約（民法555条）。諾成契約（書面不要・口頭でも成立）、有償契約、双務契約。不動産売買は法律上書面不要だが、実務では売買契約書を作成する（宅建業法では37条書面交付義務）。",
