    exp3: "売買契約は所有権移転の効果を含むが、登記（対抗要件）は別途必要だ。不動産売買は諾成契約なので意思表示が合致した時点で所有権が移転するが、登記しなければ第三者に対抗できない。したがって「契約成立→所有権移転」と「登記→第三者対抗力取得」は別の効果として区別して考える必要がある。\n\n**覚え方**\n売買契約は「言葉だけで成立・でも登記しないと旗を立てられない」。申込みは一方通行、承諾が返ってきて初めて契約成立。",
