    exp1: "手付とは、売買契約の締結時に買主から売主へ交付される金銭その他の有価物。種類：証約手付（契約成立の証拠）、解約手付（解除権を留保）、違約手付（違約の場合の損害賠償予定）。民法上は別段の合意がない限り解約手付と推定される。解約手付による解除は相手方が「履行に着手した後」はできない。",
    exp2: "「履行の着手」の意味が頻出だ。買主の履行着手→残代金の提供・中間金の支払い等（単なる準備行為は着手に含まれない）。売主の履行着手→引渡準備（鍵の引渡準備）・移転登記申請等。「履行の着手＝完了」ではなく着手した段階で手付解除不可となる。宅建業法では売主が業者の場合、手付金は代金の20%以内（t145）と規制されている。手付金が20%を超えた部分は無効で受け取れない。",
