    exp1: "手付解除とは、解約手付によって留保された解除権を行使すること（民法557条）。買主→手付を放棄して解除。売主→手付の倍額を現実に提供して解除。行使できる期間：相手方が「履行に着手するまで」。履行着手後は手付解除不可。宅建業法：売主が宅建業者の場合、手付による解除の制限は消費者保護のため特別に規制される。",
    exp2: "「どの行為が履行の着手か」が毎年のように出題される。判例上の履行着手：売主→登記申請（抹消登記や移転登記の準備も含む）・引渡準備（鍵を用意して相手方を呼ぶ等）、買主→残代金の提供・中間金支払。履行着手でないもの：ローン申込み・履行期の到来のみ（日付が来ても自動的に着手とはならない）・引越準備等の事実行為。「相手方の着手」が基準で、自分が着手しただけでは自分の解除が妨げられない。",
