    exp1: "契約不適合責任とは、引き渡された目的物が種類・品質・数量において契約内容に適合しない場合の売主の責任（民法562条以下）。2020年改正で「瑕疵担保責任」から変更。「隠れた瑕疵」要件が不要になり、契約内容との不適合が基準となった。買主の権利：①追完請求（修補・代替物・不足分）、②代金減額請求、③損害賠償、④解除。",
    exp2: "「通知期間」が頻出だ。買主は不適合を知った時から1年以内に売主に「不適合の旨の通知」をしなければならない（民法566条）。通知しないと原則として追完・減額・損害賠償・解除のすべての権利を失う。ただし売主が悪意または重大な過失で不適合を知らなかった場合は1年制限なし（売主側に制裁）。通知は「不適合の種類・程度をある程度特定して行う」必要があり（最高裁判例）、「欠陥があるらしい」という漠然とした通知では不十分とされる。",
    exp3: "宅建業者が売主の場合の特則（宅建業法40条）：引渡日から2年以上の担保期間を設ける特約は有効。2年未満を設ける特約は無効で「引渡日から2年」に戻る（買主保護）。民法の通常ルール（知った時から1年）より買主に有利な基準が設定されており、この差が試験で問われる。\n\n**覚え方**\n契約不適合責任は「言った通りの物を渡す義務」。違ったら1年以内に通知→その後に各種権利行使ができる。通知が命綱。\n\n**覚え方**\n契約不適合責任は「言った通りの物を渡す義務」。パンフレットと違う・雨漏りする・面積が足りない→全部責任を問える。",
