    exp1: "追完請求とは、引き渡された目的物が契約不適合の場合に、買主が売主に対して目的物の修補・代替物の引渡・不足分の引渡を請求する権利（民法562条）。原則として買主が追完の方法を選択できる。ただし買主が選んだ方法が売主に不相当な負担を課す場合は、売主は別の方法で追完できる（売主の選択権）。",
    exp2: "追完が不可能または売主が追完を拒絶した場合→代金減額請求（t050）が可能だ。追完請求と代金減額請求は段階的な関係にある（原則まず追完請求→相当期間内に追完がなければ代金減額請求）。ただし追完不能・明らかな拒絶・催告しても無意味な場合は直接代金減額請求可能（催告不要）。買主が自ら修補業者を雇って修理した場合、その費用は損害賠償として請求できる（追完請求の代わりに損害賠償を選ぶことも可能）。",
    exp3: "追完請求と損害賠償請求は競合する。修補してもらいつつ（追完請求）、修補完了まで物件を使用できなかった損害（賃料相当損害等）を損害賠償請求することも可能。また追完を請求せずに最初から損害賠償（修補費用相当）を請求することも認められる（選択的行使）。\n\n**覚え方**\n追完請求は「直してほしい権利」。直してくれなければ代金を減らす（減額請求）か、自分で直して費用請求（損害賠償）に切り替えられる。",
