    exp1: "代金減額請求とは、目的物の契約不適合につき売主が追完をしない場合に、不適合の割合に応じて代金の減額を請求する権利（民法563条）。原則として相当期間を定めた催告後に追完がない場合に行使できる（催告型）。例外として催告不要の場合：①追完不能、②売主が追完を明確に拒絶、③定期行為で履行期経過、④催告が明らかに無意味な場合。",
    exp2: "「催告型と無催告型の区分」が試験頻出だ。代金減額請求は形成権（相手方の同意不要で一方的に行使できる・相手方が拒否しても法的効果が生じる）。減額の割合は「不適合の程度に応じた割合」（不適合な面積の割合・品質低下の割合等）。催告不要となる場面（追完不能・明確な拒絶・催告が明らかに無意味）を具体的に覚えておくことが試験攻略に役立つ。",
    exp3: "代金減額請求・追完請求・解除・損害賠償の4つの権利は独立して行使できる（一部重複あり）。「契約不適合責任の4つの権利」として一覧で整理しておく。この中で「代金減額請求」だけが形成権（相手の同意不要）だという点が重要。解除も形成権だが、解除には「解除できる要件（催告後不履行・履行不能等）」が必要な点で代金減額と異なる。\n\n**覚え方**\n代金減額請求は「悪かった分だけ値引き要求」。まず直してと言って、直してくれなければ値段を下げさせる順番が原則。\n\n**覚え方**\n代金減額請求は「悪かった分だけ払い戻し」。買い直しも解除もしたくないが、その分お金は返してほしい時に使う権利。",
