    exp1: "被用者（従業員等）がその事業の執行につき第三者に損害を加えた場合、使用者は損害を賠償する責任を負う（民法715条）。「業務執行中」が要件で、完全な私用中の行為には適用されない。使用者が相当の注意をしていても免責されにくい。",
