    exp3: "「相続放棄は死亡日から3か月」と思いがち。「相続の開始があったことを知った時から」が正確な起算点。\n\n**覚え方** 「知ってから3か月・家裁へ・初めからゼロ」の三点セット。知らなければ期間はカウントされない。",
