    exp1: "不動産物権変動（売買・相続・抵当権設定等）を第三者に対抗するためには登記が必要（民法177条）。二重譲渡の場合、先に登記を備えた方が優先する。代金の支払いや引渡しだけでは対抗要件として不十分。",
