    exp1: "登記事項証明書（旧登記簿謄本）は法務局（登記所）が交付する不動産の登記情報を証明する公文書。「表題部（土地・建物の物理的状況）」「権利部甲区（所有権）」「権利部乙区（抵当権等の所有権以外の権利）」の3部構成。誰でも手数料を払えば取得できる。",
