    exp1: "表題登記（表示登記）とは、建物新築後または土地の分筆・合筆等の際に行う最初の登記で、不動産の物理的状況（所在・地番・地目・地積・床面積等）を公示する。新築建物は完成後1か月以内に申請義務（不動産登記法47条）。",
