    exp1: "区分所有権とは、1棟の建物を複数の独立した部分（専有部分）に分けて、各部分を独立した所有権の目的とする権利（区分所有法）。マンションの各住戸がこれに該当。専有部分以外（廊下・エントランス等）は共用部分として全区分所有者の共有となる。",
