    exp1: "共用部分は、廊下・階段・エレベーター・外壁等の複数の区分所有者が共有する部分（区分所有法4条）。「法定共用部分」（構造上当然に共用となる部分）と「規約共用部分」（規約で共用と定めた部分、例：管理人室）に分かれる。共用部分の変更には集会決議が必要。",
