    exp1: "管理組合は区分所有法3条に基づき、建物・敷地・附属施設の管理のために区分所有者全員で構成される団体。加入に選択の余地はなく、区分所有者になった時点で自動的に構成員となる。管理組合は管理者（理事長等）を置くことができる。",
