    exp1: "特別決議は区分所有者および議決権の各3/4以上の賛成が必要（区分所有法17条・31条）。規約の設定・変更・廃止、共用部分の重大な変更（形状・効用の著しい変更を伴うもの）等に適用される。30人中22人では22÷30≒0.733で3/4（0.75）に届かない。",
    exp2: "建替え決議（t073）はさらに厳しく4/5以上が必要。普通決議（1/2超）・特別決議（3/4以上）・建替え決議（4/5以上）の3段階を混同しないこと。特別決議は定数要件なので欠席者をどう扱うかも注意。",
    exp3: "「3/4以上」を「3/4超」と誤読しがち。「以上」は3/4ちょうど（75%）でも成立。\n\n**覚え方** 「特別決議＝75%ライン・規約変更・共用変更に必要」。75を覚えれば3/4が出てくる。",
