    exp1: "建替え決議は区分所有者および議決権の各4/5以上の賛成が必要（区分所有法62条）。最も厳しい決議要件で、老朽化・危険化したマンションの建替えに適用される。35÷40＝0.875で4/5（0.80）以上のため有効。",
    exp2: "建替え決議後、賛成しなかった区分所有者に対して参加または売渡しを催告できる（区分所有法63条）。売渡し請求制度により、反対者の専有部分を買い取ることができる。建替え決議には専門家（弁護士等）を招集した説明会の事前開催が必要。",
    exp3: "「建替えは全員同意」は誤り。4/5（80%）以上で成立し、反対者には売渡し請求で対応可能。\n\n**覚え方** 「建替え＝80%ライン（4/5）」。特別決議75%よりさらに高いハードル。",
