    q: "次の状況に当てはまるのは？",
    choices: [{"text":"借地権は建物の所有を目的として他人の土地を使用する権利で、存続期間は最低30年","correct":true},{"text":"借地権は建物があれば用途を問わず成立し、期間の定めは不要","correct":false,"hint":"借地権は「建物所有目的」が必須要件。期間も最低30年の規制がある。"}],
    exp1: "借地権とは、建物の所有を目的とする地上権または土地の賃借権（借地借家法2条）。借地権の存続期間は30年が最低限（当事者が30年より長い期間を定めることは可）。青空駐車場のための土地使用は建物所有目的でないため借地権にならない。",
    exp2: "借地権には「普通借地権（t075）」「定期借地権（t076）」等の種類がある。普通借地権は更新が原則、定期借地権は更新なし・期間満了で終了。借地権付き建物は土地を所有しないため、所有権付き建物より価格が低くなる傾向がある。",
    exp3: "「駐車場用地の賃借も借地権」は誤り。建物所有目的がない場合は借地借家法の保護を受けない。\n\n**覚え方** 「借地権＝建物を建てるための土地借り・最低30年」。駐車場・農地は対象外。",
