    q: "次の状況に当てはまるのは？",
    choices: [{"text":"HにはIの更新拒絶に足りる正当事由がなく、借地権は更新される","correct":true},{"text":"期間が満了したのだから、地主Hは更新を拒絶できる","correct":false,"hint":"普通借地権は地主側からの更新拒絶に正当事由（自己使用の必要性等）が必要。"}],
    exp1: "普通借地権は、期間満了時に借地人が更新を請求した場合、または建物がある状態で期間満了後も継続使用した場合に、原則として更新される（法定更新・借地借家法5条）。地主が更新を拒絶するには「正当事由」が必要で、単なる「期間満了」だけでは拒絶できない。",
    exp2: "正当事由（t084）とは、地主側の土地使用の必要性・借地人の不信行為・財産上の給付（立退料）等を総合的に判断して認められる。普通借地権の第1回更新後の期間は20年、以降は10年ごとに更新される。",
    exp3: "「期間満了＝自動的に終了」は誤り。普通借地権は借地人保護が強く、正当事由なしに返させることはできない。\n\n**覚え方** 「普通借地＝原則更新・地主は正当事由なしに断れない」。借地人が強く守られている。",
