    exp1: "定期借地権は、借地借家法22〜24条が定める「更新のない借地権」。一般定期借地権は50年以上・建物の用途不問・書面または電磁的記録による設定が必要。期間満了で更新なく土地を原状回復して返還する。普通借地権の更新強制を回避できる地主側に有利な制度。",
    exp2: "定期借地権には3種類ある：①一般定期借地権（50年以上・用途不問）②事業用定期借地権（10年以上50年未満・事業用専ら・公正証書必須）③建物譲渡特約付借地権（30年以上・期間後建物を地主に譲渡）。試験では3種類の違いが問われる。",
    exp3: "「定期借地＝30年以上」は事業用の数字。一般定期は50年以上。混同しないよう整理する。\n\n**覚え方** 「定期借地＝更新なし確定終了。一般は50年以上、事業用は10〜50年未満」。",
