    exp1: "事業用定期借地権は、専ら事業の用に供する建物（居住用除く）の所有を目的とする定期借地権（借地借家法23条）。存続期間は10年以上50年未満で、公正証書による書面設定が法定要件。コンビニ・ファミレス・ロードサイド店舗等に広く利用される。",
    exp2: "「専ら事業用」が要件なため、事業用と居住用が混在する建物（例：1階店舗・2階居住）には適用できない。一般定期借地権（t076）と異なり公正証書が必須で、公正証書以外の書面では無効となる点が重要。",
