    exp1: "建物譲渡特約付借地権は、借地権設定後30年以上経過した時点で、地主（設定者）が相当の対価で借地人から建物を買い取る旨の特約を付した借地権（借地借家法24条）。期間満了後、地主が建物を取得し借地権は消滅する。公正証書は不要（一般定期・事業用定期と異なる）。",
