    exp1: "借家権とは建物の賃借人が持つ賃借権。通常の債権は当事者間にのみ効力があるが、借地借家法31条により建物の「引渡」を受けていれば、その後の建物の所有権取得者（新オーナー）に対しても対抗できる（対抗力）。登記は不要。",
