    exp1: "普通借家権では、貸主（家主）が更新拒絶するには「正当事由」が必要（借地借家法28条）。正当事由の判断には①家主側の使用必要性②借主側の使用必要性③貸主の立退料提供等を総合考慮する。「家賃を上げたい」「建替えたい」だけでは不十分。",
