    exp1: "弁済とは、債務者が債務の内容を実現して債権を消滅させること（民法473条）。第三者（保証人等）が弁済した場合を「第三者弁済」または「代位弁済」という。代位弁済をした保証人は、債権者に代位して（代位弁済者は債権者の地位を取得）、主債務者に対して求償権を行使できる（民法499条・500条）。",
