    exp1: "相殺とは、対立する同種の債権（双方が金銭債権等）が弁済期にある場合に、一方の意思表示のみで対等額を消滅させる制度（民法505条）。相手方の同意は不要（単独行為）。相殺の要件は①双方の債権が存在②同種の目的の給付③双方の弁済期が到来していること。",
    exp2: "不法行為による損害賠償債務を受動債権として相殺することは禁止（民法509条）。差押禁止債権を受動債権とする相殺も禁止。相殺禁止特約も可能。相殺の意思表示は条件・期限を付してはならない（相殺は即時確定が原則）。",
    exp3: "「相殺は相互同意が必要」は誤り。相殺は一方的な意思表示で成立する単独行為。ただし不法行為債務等は相殺禁止。\n\n**覚え方** 「相殺＝一方通行でOK。お互いの借金をチャラにする宣言」。同意なく単独で使える。",
