    exp1: "停止条件とは、条件が成就するまで法律行為の効力が発生しない条件（民法127条1項）。「ローン審査通過を条件とする売買」は停止条件の典型例。条件成就前でも当事者は条件付き権利を有し、その侵害に対して損害賠償を請求できる（民法128条）。",
    exp2: "宅建実務でよく使われる「ローン特約（融資利用の特約）」は停止条件の一種として理解できる。停止条件成就の効果は遡及しない（成就時から将来に向かって効力発生）のが原則だが、特約で遡及させることも可能。",
    exp3: "「停止条件成就前は完全に権利なし」は誤り。条件付き権利として保護され、侵害への損害賠償請求は可能。\n\n**覚え方** 「停止条件＝スイッチONになる条件。成就前でも権利は守られる」。",
