    exp1: "委任とは、当事者の一方（委任者）が相手方（受任者）に法律行為の処理を委託し、受任者がこれを承諾する契約（民法643条）。受任者は善管注意義務（t096）を負い、委任事務の範囲内で委任者の利益のために行動しなければならない。",
    exp2: "委任は当事者の信頼関係を基礎とするため、いつでも解除できる（民法651条）。ただし相手方に不利な時期の解除は損害賠償義務が発生することがある。不動産売却の委任における宅建業者への媒介委任と、代理権の授与を混同しないよう注意。",
    exp3: "「委任があれば受任者は何でもできる」は誤り。委任の範囲を超えた行為は無権代理（t007参照）となり、本人は責任を負わない。\n\n**覚え方** 「委任＝信頼の契約。善管注意義務あり・範囲外は無権代理」。任された範囲内だけが有効。",
