    exp1: "物権的請求権は、所有権等の物権が侵害された場合に、侵害者に対して侵害の排除を請求できる権利（民法上明文はないが慣習法・判例上認められる）。①返還請求権（占有を回復）②妨害排除請求権（侵害状態の除去）③妨害予防請求権（将来の侵害予防）の3種類がある。",
    exp2: "物権的請求権は損害賠償（不法行為・t051）とは異なり、過失・故意を問わず行使できる。また時効消滅しないとされる（判例）。所有者は侵害者の資力・信用に関係なく現物での排除を請求できる。",
