    exp1: "8種制限（宅建業法第39条〜第47条の2）とは、宅建業者が自ら売主・買主が非業者の売買において適用される消費者保護規定群。民法の任意規定より買主に有利な条件でなければ、特約を無効とするものが多い。賃貸借には適用されない。",
    exp2: "8種の内訳と各制限のポイント（試験頻出）：①クーリングオフ（8日・書面）、②損害賠償予定の制限（20%以内）、③手付額の制限（20%以内）、④手付金等の保全（5%/10%超で必須）、⑤他人物売買の制限、⑥瑕疵担保特約の制限（2年以上）、⑦割賦販売の規制、⑧所有権留保禁止。",
