    exp1: "業務停止処分は、指示処分に違反した場合や宅建業法上の一定の違反行為をした場合に、1年以内の期間を定めて業務の全部または一部を停止させる処分。免許取消の一段下に位置し、停止期間中は新規契約の締結ができない。",
    exp2: "処分の3段階（指示処分→業務停止→免許取消）の中で「業務停止」は中間に位置する。試験では「業務停止の最長期間（1年以内）」「業務停止の対象違反行為」「停止中に許される行為の範囲」の3点が問われる。業務停止中でも、既存契約の引渡し・登記移転・残金決済など「締結済み契約の義務の履行」は継続可能。一方で新規の媒介契約締結・勧誘行為は禁止される。「最長2年以内」「最長6か月」はどちらも典型的な誤り選択肢。また業務停止処分中に新たな違反を犯した場合は免許取消処分（→t151）への格上げがあり得る点も覚えておく。",
    exp3: "業務停止と免許取消の最大の違いは「期間の有無」。業務停止は期間満了後に自動的に業務再開できる。免許取消は期間の定めなく業務不能となり、再開には5年後に再免許申請が必要（→t151）。指示処分（→t153）との3段階の処分体系を比較表で整理し、違反の重さに対応する処分レベルを正確に把握すること。\n\n**覚え方** 「業務停止は1年以内の謹慎・期間終了で自動復活。免許取消は退学で5年後に再入学申請」——停学と退学の対比に既存契約履行の例外もセットで記憶。",
