    scenario: "不動産仲介業者に勤める自分の会社が、重要事項説明書の一部記載漏れを指摘され、都道府県知事から「業務の適正化を図るよう」との文書を受け取った。罰金や業務停止ではなく、まず改善せよという命令らしい。",
