    exp1: "監督処分とは、宅建業者または宅建士が宅建業法等に違反した場合に免許権者等が行う行政処分の総称。宅建業者に対しては①指示処分②業務停止処分③免許取消処分の3種類がある。国土交通大臣免許業者の免許取消は大臣のみだが、指示・業務停止は業者の所在する都道府県の知事も行使できる。",
