    exp1: "宅建士は正当な理由がある場合を除き、宅建業の業務上知り得た秘密を他に漏らしてはならない。この義務は宅建士でなくなった後（退職・廃業・登録消除後）も同様に適用され、期間の定めなく継続する。正当な理由の例としては裁判の証人として証言する場合等がある。",
    exp2: "試験では「退職後も義務が継続するか（継続する）」「正当な理由がある場合に漏洩は許されるか（許される）」の2点が問われる。正当な理由として認められる例は①法令に基づく義務的な開示（裁判の証人として証言等）②本人（顧客）の同意がある場合③公益上の必要性が明らかな場合等。正当理由として認められない例は競合他社への情報提供・個人的な利益のための利用等。義務違反をした場合は宅建士登録の取消事由（→t156）に該当し、退職後でも行政処分を受け得る。また登録を消除されると欠格事由（5年間登録不可・→t156）が生じる。",
    exp3: "「本人同意があれば漏洩は自由」は過言。同意は正当理由の1つに過ぎず、同意の形式・範囲を超えた利用は義務違反となる場合がある。また「退職してから日が経てば義務が消える」という誤解にも注意。期間の定めなく継続する点を明確に記憶する。\n\n**覚え方** 「退職しても秘密は墓場まで。違反すれば登録消除・5年欠格のリスクも退職後に及ぶ」——義務の永続性と違反の重大性をセットで記憶。",
