    exp1: "宅建業者は、自己の名義を他人に使用させて宅建業を営ませてはならない（宅建業法13条）。これは実質的な無免許営業を幇助する行為であり、名義を貸した業者は免許取消処分や刑事罰（3年以下懲役または300万円以下罰金）の対象となる。",
    exp2: "試験では「名義貸しが禁止される理由（実質的な無免許営業の幇助）」「違反した場合の処分の重さ（免許取消・刑事罰）」「実際の業務関与の有無と違法性の関係」が問われる。名義を使用して業務をした側は無免許営業（→t155）の罪に問われ、名義を貸した側は宅建業法13条違反として免許取消処分（→t151）および3年以下の懲役または300万円以下の罰金（→t155）の対象となる。関与の有無にかかわらず名義を貸すこと自体が違法であり、「書類上だけ」「口だけ」でも実態として名義を使わせれば違法。",
