    scenario: "不動産営業マンとして売主側を担当した案件で、売主が「資金繰りの都合」を理由に、引渡しを半年先送りにしようとしている。買主はもう代金を支払っているのに、引渡しが遅れる状況。この売主の行為は宅建業法上問題があるか？",
