    exp1: "宅建業者は、相手方に不当な利益をもたらす目的で、投資等の取引について一任代理等の名目で不当に関与することを禁じられている。これは投資詐欺的な手口から消費者を守る規定で、宅建業法43条に規定されている。",
    exp2: "試験での出題頻度は低いが、「どのような一任代理が禁止されるか」の判定問題として出ることがある。違法性の判断基準は「不当な利益を得る目的があるかどうか」であり、通常の代理・媒介契約（顧客の利益を中心に行動する契約）とは区別される。「顧客が同意しているから合法」という論理は通用せず、同意があっても不当利益構造があれば違反となる。この規定は主に不動産投資詐欺的な手口（顧客の資金を一任させて不当に費消する）を防ぐことを目的とし（宅建業法43条）、断定的判断の提供禁止（→t164）・不当勧誘禁止（→t165）と同系統の消費者保護規定として位置付けられる。",
    exp3: "通常の媒介契約（売主・買主から手数料を受け取る正規の代理業務）は適法。「一任代理」という名称がついていても、不当利益目的がなければ直ちに違反とならない。問題は契約の名称ではなく実態（誰が利益を得る構造か）。断定的判断の提供（→t164）・不当勧誘（→t165）と組み合わせて、宅建業法が規制する「悪質勧誘の3パターン」として一括整理する。\n\n**覚え方** 「一任代理の違法性は目的次第。不当利益構造があれば顧客同意があっても禁止」——代理の名称より実態（利益の帰属）で判断する点を記憶。",
