    keyword: "37条書面の必要的記載事項",
    scenario: "不動産営業マンの自分が、売買契約書（37条書面）の作成を担当している。契約解除の条件・方法・違約金の有無を記載し忘れた場合、問題になるのかどうか確認したい。",
