    term: "支払金・預かり金の保全",
    cat: "業法",
    freq: "mid",
    diff: "mid",
    keyword: "業者が受領する金銭の保全措置・35条書面記載",
    scenario: "マイホームを購入しようとしている30代会社員の自分が、手付金や申込証拠金を不動産業者に支払った直後に、業者が倒産したというニュースを聞いた。自分が払ったお金は保全されているのか不安になっている。",
    q: "次の状況に当てはまるのは？",
