    q: "次の状況に当てはまるのは？",
    choices: [{"text":"宅地造成等規制法の規制区域内で一定規模の宅地造成を行う場合は、都道府県知事の許可が必要である","correct":true},{"text":"宅地造成はどこで行っても届出だけでよく、許可は不要である","correct":false,"hint":"規制区域内では許可が必要。"}],
    exp1: "宅地造成とは、宅地以外の土地を宅地にするため、または宅地において行う土地の形質変更（切土・盛土・整地等）をいう。宅地造成等規制法（2023年改正で「盛土規制法」に改称）に基づき、規制区域内で一定規模以上の造成工事を行う場合は都道府県知事の許可が必要。",
    exp2: "試験では「許可が必要な造成の規模要件（切土2m超・盛土1m超・合計2m超・面積500㎡超のいずれか）」「許可権者（都道府県知事）」「2023年改正による新制度（特定盛土等規制区域）」が問われる（2026年現在）。2023年（令和5年）改正で旧「宅地造成工事規制区域」に加えて「特定盛土等規制区域」（土砂災害リスクが高い山林・農地等でも指定可能）が新設された。規制区域外でも特定盛土等規制区域内であれば別途規制が及ぶ。改正前の旧法では「宅地」目的の造成のみが対象だったが、改正後は農地・森林等への盛土工事も対象範囲に含まれている（→t244参照）。",
    exp3: "宅地造成等規制法は2023年（令和5年）改正で「宅地造成及び特定盛土等規制法（盛土規制法）」に改称・大幅改正された。旧法（改正前）の名称・規制内容・数値が試験に出た場合は改正後の内容が現行法。旧法の「宅地造成工事規制区域のみ」という理解から、「宅地造成工事規制区域＋特定盛土等規制区域」の2区域制に更新する（→t244・t245参照）。\n\n**覚え方** 「盛土規制法＝2023年改正で2区域制に。切土2m超・盛土1m超・500㎡超は知事の許可が必要」——改正年・2区域・規模要件の3点セットで記憶。",
