    scenario: "法務担当者の自分が、取引相手が「被補助人」であると確認した。被保佐人より保護の程度が軽いと聞いたが、具体的にどんな行為に補助人の同意が必要かを確認したい。",
    q: "次の状況に当てはまるのは？",
