    exp1: "準都市計画区域とは、都市計画区域外にあって、高速道路IC周辺など無秩序な開発が懸念される区域を都道府県が指定するエリア。用途地域等の一部の都市計画制限を適用できる。市街化区域のような積極的開発推進ではなく、無秩序な開発を抑制するための制度。",
    exp2: "試験では「準都市計画区域に定めることができる都市計画の内容」と「定めることができない内容」の区別が問われる。定めることができるもの：用途地域・特別用途地区（→t208）・特定用途制限地域（→t209）・高度地区・景観地区（→t246）・地区計画（→t247）等。定めることができないもの：市街化区域・市街化調整区域の区分（線引き）は定めることができない（準都市計画区域は線引きの前提がない）。また準都市計画区域での開発許可面積基準は3,000㎡以上（非線引き区域と同じ）。指定主体は都道府県（→t202と同様）。",
    exp3: "「都市計画区域外＝何でもあり」ではない。準都市計画区域の指定により一定の規制が及ぶ。IC周辺・幹線道路沿い・リゾート地等が典型的な指定対象。また準都市計画区域は「都市計画区域に昇格させるほどではないが放置すると無秩序な開発が進む区域」という位置付けで、将来的に都市計画区域に組み込まれることもある。\n\n**覚え方** 「準都市計画区域＝都市計画区域外の無秩序開発ストッパー。IC周辺の野放しを防ぐ。線引きは不可・用途地域は任意」——「準」の字と「都市計画区域外」という位置づけをセットで記憶。",
