    exp1: "特別用途地区とは、用途地域内において特別の目的（商業の振興・文教地区の保護・風致の維持等）から、用途地域の建築制限を補完・強化・緩和するために定める地区。市区町村条例によって具体的な制限内容を定める。文教地区・観光地区・特別工業地区・研究開発地区などが典型例。",
    exp2: "試験では「特別用途地区と特定用途制限地域の違い」が最頻出。特別用途地区＝用途地域「内」に重ねて指定、特定用途制限地域（→t209）＝用途地域「外（未指定区域）」に指定。この内外対比が決め手。また特別用途地区の制限内容は「条例」で定めるという点も押さえる（上乗せ規制は条例ベース・都市計画そのものではない）。典型例：文教地区（大学周辺で風俗施設を禁止する条例）・特別工業地区（工場の種類を制限）・研究開発地区・娯楽・レクリエーション地区など。また特別用途地区内では用途地域の制限を「緩和」することもでき（条例で国土交通大臣の承認を得た上で）、柔軟な土地利用が可能。",
    exp3: "「特別用途地区」と「特定用途制限地域（→t209）」の名称が紛らわしい。「内か外か」で完全に使い分ける。用途地域の中に上書きするのが「特別用途地区」、外側に初めて適用するのが「特定用途制限地域」。両者とも「条例で具体的内容を定める」点は共通。試験では名称と指定場所（内か外か）の組み合わせ正誤問題が出る。\n\n**覚え方** 「特別（上乗せ）は用途地域の中、特定（外出し）は用途地域の外。内外の『別』と『定』で覚える」——「特別・内側」「特定・外側」の対比を漢字の意味から記憶。",
