    exp1: "特定用途制限地域とは、用途地域が定められていない区域（非線引き都市計画区域・準都市計画区域）において、特定の用途の建築物の立地を制限するために定める地域地区。ラブホテル・パチンコ店・大型商業施設など、地域環境に不調和な建物の立地を防ぐ目的で使われる。市区町村条例で制限内容を定める。",
    exp2: "「特定用途制限地域が定められる区域（用途地域が定められていない区域＝非線引き都市計画区域・準都市計画区域）」が試験の正解肢になる。市街化区域には用途地域が必ず定められているため特定用途制限地域は定められない。市街化調整区域にも原則として用途地域がないが、特定用途制限地域の指定対象には含まれない（調整区域には開発規制があるため追加的な制限が不要）という細かい区別も重要。また「特定用途制限地域で制限できる内容は特定の建築物の用途のみ（形態・意匠は景観地区→t246が担当）」という機能の分担も確認する。",
    exp3: "名称が「特別用途地区（→t208）」と紛らわしい。「特定用途制限地域」は用途地域「外」の用途ブロック制度。「特別用途地区」は用途地域「内」の上乗せ規制。また両者とも「条例で具体的内容を定める」点は共通だが、条例制定の根拠法が異なる（特別：建築基準法、特定：都市計画法）点も理解する。\n\n**覚え方** 「特定（外出し）は用途地域ゼロエリアで特定の用途だけをブロック。特別（内）は用途地域の中での上乗せ。内外の『特別vs特定』対比」——位置（内外）と目的（上乗せvsブロック）の違いをセットで記憶。",
