    exp1: "2項道路（建築基準法42条2項道路）とは、建築基準法施行時（昭和25年11月23日）に存在していた幅員4m未満の道で、特定行政庁が建築基準法上の道路として指定したもの。この道路に面した敷地で建築を行う場合は、「道路の中心線から水平距離2m以上後退（セットバック）」した線を道路境界線とみなして建築しなければならない。",
    exp2: "セットバックした部分は建築基準法上「道路」とみなされるため（建築基準法42条2項後段）、建蔽率・容積率の計算上の敷地面積からセットバック部分を除外して計算する。試験では「後退基準が中心線か境界線か（中心線が正解）」「セットバック部分は建蔽率・容積率の計算に含めるか（含めない）」「セットバック部分への建築可否（不可）」が頻出。例外：川・崖等で後退できない場合（片側のみ後退できる場合）は道路側の境界線から4m後退する特例がある（建築基準法42条2項ただし書き）。また「セットバック後の道路幅員（4m）で容積率の前面道路制限（→t217）を計算する」点も試験に出る。",
    exp3: "「道路境界線から2m」と「道路中心線から2m」は全く異なる。既存の道路幅員が2mの場合、中心線から2m後退すると道路全体で4mになるイメージ（中心から左右各2m＝合計4m幅の道路完成）。境界線基準だと道路外まで後退することになり不正確。また「セットバック部分の土地は所有権は自分にあるが道路として扱われる」点が試験のひっかけになる（→t220 セットバックとの関係）。\n\n**覚え方** 「2項道路のセットバックは中心線から2m後退。真ん中から両側に2mずつ広げて4m道路に育てるイメージ。セットバック部分は道路扱いで建蔽率・容積率の計算から除外」——「中心線基準」と「計算除外」の2点をセットで記憶。",
