    exp1: "セットバックとは、2項道路（幅員4m未満のみなし道路）に接する敷地において、道路の中心線から水平距離2mの線まで後退することをいう。後退した部分は建築基準法上「道路」とみなされる。この結果、①後退部分に建築物を建てることはできない、②建蔽率・容積率の計算上、後退前の敷地面積から後退部分の面積を差し引いた面積を使用する。",
    exp2: "試験では「セットバック後の敷地面積を使って建蔽率・容積率を計算する問題」が出る。例：元の敷地100㎡・セットバック面積5㎡→建蔽率・容積率計算に使う敷地面積は95㎡→建蔽率60%の場合の建築面積上限は95㎡×60%＝57㎡（元の100㎡×60%＝60㎡ではない）。また「セットバック部分への工作物設置」（門・塀・フェンス等）も原則禁止（道路として扱われるため）。「川やがけ等後退できない側がある場合は境界線から4m後退（片側後退の特例）」の数値変化（後退量が2mでなく4mになる）も押さえる（→t219 2項道路との連動）。",
    exp3: "セットバック部分の土地は「自分の所有地だが道路として扱われる」という点が試験のひっかけ。所有権はあるが建築・工作物の設置はできない。固定資産税については非課税または減額措置が受けられる場合が多いが、これは税法の話（→t215 建蔽率計算との連動）。セットバックを行っても「4m道路になるのは将来的に両側がセットバックした後」であり、現時点では片側だけが後退していることも多い点が実務上の注意点。\n\n**覚え方** 「セットバックは自分の土地を道路に提供して4m道路を育てる犠牲。計算上はセットバック後の面積（小さくなった敷地）で建蔽率・容積率を計算」——「犠牲した面積は計算から除外」を中心に記憶。",
