    exp1: "建築協定（建築基準法69条〜77条）とは、住宅地の環境保全や商業地の利便向上のために、土地所有者・借地権者等が建築基準法の制限に加えた独自の建築ルールを合意で定め、特定行政庁の認可を受ける制度。高さ・外壁後退距離・屋根形状・色彩等について、法律の規制より厳しいルールを任意に定めることができる。",
