    exp1: "高度地区（建築基準法58条）とは、用途地域内において、市街地の環境の維持向上を目的に建築物の高さの最高限度または最低限度を定める地域地区。最高限度を定めれば低層住宅地の環境保護に、最低限度を定めれば土地の高度利用を促進できる。具体的な高さ数値は都市計画で定められる。",
