    exp1: "高度利用地区（建築基準法59条）とは、用途地域内において、土地の高度利用と都市機能の更新を図るため、容積率の最高・最低限度、建蔽率の最高限度、建築面積の最低限度、壁面の位置を定める地区。低層ビルや空き地のまま放置されることを防ぎ、容積率の最低限度を設けることで土地の積極的活用を促す。再開発地区や駅前などに多い。",
