    exp1: "農地法3条とは、農地または採草放牧地を農地・採草放牧地として（現状のまま）所有権・賃借権等の権利を移動する場合に必要な農業委員会の許可制度。売買・贈与・交換・賃貸借等すべての権利移動に適用される。許可の基準は「権利を取得する者が農業経営に使用すること」等。相続・遺贈（相続人への）・時効取得は3条の許可不要だが、農業委員会への届出が必要。",
    exp2: "「3条許可が不要な場合」として、相続・包括遺贈（相続人以外への遺贈は許可必要）・競売による取得・土地収用等が試験で問われる。また3条の許可申請は農業委員会経由で都道府県知事に提出する場合（4ヘクタール超の農地等）もある。農業委員会への届出のみで足りるケースと混同しないよう注意。",
    exp3: "「親族間」「隣の農家への賃貸」「農家同士の交換」など、いかにも農業目的に見えるケースでも3条許可が原則必要。例外（相続等）を除き、農地の権利移動には必ず農業委員会の許可が必要。\n\n**覚え方** 「農地3条＝農地のまま渡す→農業委員会OK出してから」。農地を農業以外に使わせない守りの許可。",
