    choices: [{"text":"自己所有農地を宅地・駐車場に転用する場合は農地法4条の都道府県知事の許可が必要だ","correct":true},{"text":"自己所有農地を転用する場合は農地法4条の農業委員会の許可が必要だ","correct":false,"hint":"4条の許可権者は都道府県知事（4ヘクタール超は農林水産大臣）。農業委員会が許可するのは3条。"}],
    exp1: "農地法4条とは、農地の所有者が自己所有農地を農業以外の用途（宅地・駐車場・資材置き場等）に転用する場合に必要な許可制度。許可権者は都道府県知事（4ヘクタール超は農林水産大臣）。農業委員会は許可主体ではなく、申請書の経由機関（農業委員会経由で申請）。市街化区域内の農地の転用は、農業委員会への「届出」で足り、許可不要という重要例外がある。",
    exp2: "「市街化区域内の農地転用は届出のみ（許可不要）」は最頻出の試験知識。市街化区域は積極的に宅地化を推進する区域なので、農地転用許可の手続きを緩和している。ただし届出は必要。市街化調整区域・農業振興地域の農用地区域内では許可の基準が厳しく、原則転用できない場合もある。",
    exp3: "「4条は自己転用（権利移動なし）・許可先は知事」。農業委員会を許可先と誤答するケースが多い。農業委員会は経由機関であって許可権者ではない。また「市街化区域→届出のみ」の例外を必ず覚える。\n\n**覚え方** 「農地4条＝自分で転用するだけ（売らない）→知事の許可。市街化区域なら届出だけでOK」。",
