    exp1: "農地法5条とは、農地を農業以外の用途に転用する目的で、売買・貸借・使用貸借等の権利移動を行う場合に必要な許可制度。要するに「農地を買って宅地にする」「農地を借りて資材置き場にする」等の場合。許可権者は都道府県知事（4ヘクタール超は農林水産大臣）。市街化区域内では農業委員会への届出で足りる（4条同様の例外）。",
    exp2: "農地法の3条・4条・5条を整理する決め手：転用の有無×権利移動の有無のマトリックス。転用なし・権利移動あり＝3条、転用あり・権利移動なし＝4条、転用あり・権利移動あり＝5条。5条は「転用×権利移動の両方あり」の最も広範な規制。また5条違反（無許可転用目的売買）は許可申請命令・原状回復命令の対象となる。",
