    exp1: "農地転用とは、農地の地目・用途を農業以外の目的（住宅・駐車場・工場・道路等）に変更することをいう。農地転用には農地法4条（自己転用）または5条（転用目的の権利移動）の許可が必要。農業振興地域内の農用地区域（いわゆる「青地」）は転用が原則不可。「農地の転用規制の概念」そのものを問う出題もある。",
    exp2: "試験では「農地転用に必要な許可の種類と許可権者」「市街化区域内の届出特例」「許可不要な転用（学校・病院等の公益目的、非常災害対応等）」が繰り返し問われる。また「仮転用（工事期間中の一時使用）」にも許可が必要な点も出題されることがある。",
    exp3: "農地転用は「地目（登記簿上の分類）が田・畑かどうか」だけでなく、「現実に農地として使われているか」で判断される点が重要。登記上は農地でなくても現実に耕作中なら農地法の規制を受ける。\n\n**覚え方** 「農地転用＝農地から卒業させる手続き。卒業には知事の許可証が必要」。",
