    freq: "mid",
    diff: "mid",
    keyword: "区画整理後に従前地に対応して交付される宅地",
    scenario: "土地区画整理事業区域内に農地（200㎡）を持つ60代の自分。事業完了後に「換地処分通知」が来たが、交付された換地は170㎡だった。面積が減った理由と清算金について説明を求めている。",
    q: "次の状況に当てはまるのは？",
