    exp3: "「公示価格への強制従属」は誤り。あくまで指標・参考価格。民間取引への強制力はないが、公共事業の補償では参考にされる。\n\n**覚え方:** 「地価公示＝国交省が元日基準で公示する土地の参考価格。強制力なし」。",
