    q: "次の状況に当てはまるのは？",
    choices: [{"text":"不動産鑑定評価は、不動産鑑定士が不動産の経済価値を判定し、その結果を価額に表示することである","correct":true},{"text":"不動産鑑定評価は、宅建士であれば誰でも実施できる","correct":false,"hint":"不動産鑑定評価は不動産鑑定士（または不動産鑑定士補の補助）のみが実施できる国家資格業務"}],
    exp1: "不動産鑑定評価は、不動産の経済価値を判定しその結果を価額に表示する不動産鑑定士の専門業務（不動産の鑑定評価に関する法律）。評価によって求められる価格の種類には、正常価格（通常の市場での適正価格）・限定価格（市場が限定される場合）・特定価格（民事再生法等特定目的）・特殊価格（文化財等）がある。",
    exp2: "試験では「不動産鑑定士のみが実施できる」「正常価格・限定価格の違い」「3つの鑑定評価手法（原価法・取引事例比較法・収益還元法）」が頻出。宅建士が「不動産の価格を鑑定評価する」ことはできない点を押さえる。",
    exp3: "「宅建士が鑑定評価できる」は誤り。鑑定評価は不動産鑑定士の独占業務。宅建士は重要事項説明等が専門であり、鑑定評価はできない。\n\n**覚え方:** 「不動産鑑定＝不動産鑑定士の独占業務。宅建士にはできない」。",
