    scenario: "不動産投資家の自分が、購入を検討している土地の鑑定評価書を確認した。「取引事例比較法を採用し、地域要因・個別的要因を比較修正した」と記載されていた。どのような手順で価格を算出するのかを理解したい。",
    q: "次の状況に当てはまるのは？",
    choices: [{"text":"取引事例比較法では、多数の取引事例を収集・選択し、事情補正・時点修正・地域要因・個別的要因の比較を行って価格を求める","correct":true},{"text":"取引事例比較法では、1件の取引事例をそのまま対象不動産の価格として採用する","correct":false,"hint":"1件ではなく多数の事例を収集・選択・比較修正するのが手法の本質"}],
    exp1: "取引事例比較法は、多数の取引事例を収集・選択し、それらの事例に①事情補正（売り急ぎ等の特殊事情を除去）②時点修正（価格時点に合わせた修正）③地域要因比較（地域の優劣比較）④個別的要因比較（個別の土地条件の差異比較）を行い、対象不動産の比準価格を求める手法。土地の評価に最もよく使われる。",
    exp2: "試験では「事情補正・時点修正の意味」「多数の事例収集が必要な理由」「土地評価に有効」が問われる。1件の事例でOKという誤りの選択肢に注意。「事情補正」が最初に行われる修正（特殊事情を除去してから時点修正）という手順も押さえる。",
    exp3: "「事例1件だけでOK」は誤り。特殊な事情（急売り・親族間売買等）を含む事例を除去した上で、多数から選定する必要がある。\n\n**覚え方:** 「取引事例比較法＝多数の事例で比べて補正・修正。土地評価の定番手法」。",
