    exp1: "収益還元法は、対象不動産が将来生み出す純収益（賃料収入等から経費を控除したもの）を還元利回りで割り算（または割引）して収益価格を求める鑑定評価手法。直接還元法（一期間の純収益÷還元利回り）とDCF法（複数期間の純収益を割引現在価値で合計）がある。賃貸用・収益用不動産の評価に最適で、投資判断にも活用される。",
    exp2: "試験では「純収益÷還元利回り＝収益価格」という計算式と「投資用不動産に有効」「DCF法の存在」が問われる。「居住用自宅の評価に最適」は誤りで、収益還元法は収益を生む不動産向き。直接還元法の計算は単純だが還元利回りの設定が重要。",
    exp3: "「収益還元法＝居住用不動産の評価に最適」は誤り。収益還元法は賃料等の収益が前提の投資用不動産に向く。自己使用の不動産は取引事例比較法や原価法が適切。\n\n**覚え方:** 「収益還元法＝純収益÷利回りで価格算出。家賃を生む物件の評価に使う」。",
