    exp1: "フラット35は、住宅金融支援機構と民間金融機関が提携して提供する全期間固定金利の住宅ローン。申込先は民間金融機関（銀行・信用金庫等）で、機構は貸付債権を買い取って証券化する。利用には物件の技術基準（床面積：一戸建て70㎡以上・マンション30㎡以上、耐久性・省エネルギー性等）を満たす必要がある。完済時の年齢上限（80歳未満等）や借入比率（融資率90%超は金利上乗せ）の条件もある。",
    exp2: "試験では「全期間固定金利」「民間金融機関が窓口」「機構が証券化」「物件技術基準あり（床面積・耐久性等）」が頻出。「技術基準なし・どの物件でも可」は誤りの定番。融資率90%超（頭金10%未満）の場合に金利が上乗せされる点も押さえる。",
    exp3: "「どんな物件でもフラット35が使える」は誤り。床面積要件・耐久性等の技術基準を満たした物件のみ対象。物件検査（適合証明）が必要。\n\n**覚え方:** 「フラット35＝全固定・民間が窓口・機構が証券化。物件に技術基準あり」。",
