    exp1: "不動産の表示に関する公正競争規約は、景品表示法に基づき不動産公正取引協議会連合会が定める自主規制ルール。主な規制内容：①徒歩による所要時間の表示（80m＝1分で計算・端数は1分切上げ）②「新発売」の定義（初回広告のみ使用可）③「新築」の定義（竣工後1年以内かつ未使用）④二重価格表示の根拠・期間制限⑤物件の最小面積表示。",
    exp2: "試験では「徒歩1分の計算方法（80m＝1分）」「新発売の定義（初回広告）」「二重価格の規制」「新築の定義（竣工後1年以内かつ未使用）」が頻出。「売れ残り物件に新発売」は誤りの定番。徒歩時間は坂・信号待ちを考慮しない80m/分の機械的計算。",
    exp3: "「新発売＝いつでも使える」は誤り。初回広告時のみ。「新築」も竣工後1年以内かつ未使用でなければ使えない。\n\n**覚え方:** 「徒歩1分＝80m。新発売は初回のみ。新築は1年・未使用が条件」。",
