    choices: [{"text":"不動産取引において、土地の売買・貸付は消費税が非課税であるが、建物の売買・貸付（住宅用途を除く）は消費税の課税対象となる","correct":true},{"text":"不動産の売買はすべて消費税の課税対象となる","correct":false,"hint":"土地の売買・貸付は非課税。建物も住宅用の貸付は非課税"}],
    exp1: "消費税の不動産取引への適用：①土地の譲渡・貸付（一時的な貸付を除く）は消費税非課税②建物の譲渡は消費税課税③建物の貸付（賃貸）は居住用（住宅）は非課税、事業用・店舗・事務所は課税。住宅ローンで購入する新築マンションでは、土地部分は非課税・建物部分に消費税が課される。売買価格を土地・建物に按分して消費税額を計算する。",
    exp2: "試験では「土地非課税・建物課税」「住宅賃貸は非課税・事業用賃貸は課税」の区別が頻出。中古住宅の個人間売買（個人が事業者でない場合）は消費税がかからない点も押さえる。宅建業者が売主の場合は建物部分に消費税が課される。",
    exp3: "「土地も建物も消費税がかかる」は誤り。土地は原則非課税。住宅賃貸も非課税。事業用賃貸のみ課税という区別を確実に習得する。\n\n**覚え方:** 「土地は非課税、建物は課税。住宅賃貸は非課税、事務所賃貸は課税」。",
