    exp1: "居住用財産（マイホーム）を売却して譲渡損失が生じた場合、①住宅ローン残高がある一定の場合（オーバーローン）や②特定居住用財産の買換え損失の場合に、その損失を給与所得・事業所得等の他の所得と損益通算できる特例がある。損益通算しきれない損失は、翌年以降3年間の繰越控除が可能（合計所得金額3000万円超の年は適用不可）。",
