    exp3: "「不動産売却損は損益通算不可」は誤り。居住用財産の特例では損益通算できる。ただし合計所得3000万円超の年は不適用。\n\n**覚え方:** 「マイホーム売却損は給与と合算できる特例あり。3年繰越OK・3000万超はNG」。",
