    q: "次の状況に当てはまるのは？",
    choices: [{"text":"変動金利型住宅ローンは、通常6か月ごとに金利が見直されるが、返済額の変更は5年ごとで、かつ増加幅は直前返済額の1.25倍が上限とされることが多い","correct":true},{"text":"変動金利型は毎月金利が変動し、その都度返済額が変わる","correct":false,"hint":"金利の見直しは6か月ごと（市場金利に連動）、返済額の変更は5年ごとが一般的な仕組み"}],
    exp1: "変動金利型住宅ローンは、市場金利（短期プライムレート等）の変動に連動して定期的に金利が見直される住宅ローン。一般的な仕組み：①金利見直し：6か月ごと②返済額の変更：5年ごと③返済額の増加上限：直前の返済額の1.25倍以内（125%ルール）。固定金利型と比べると契約時の金利は低い場合が多いが、金利上昇リスクがある。",
    exp2: "試験では「6か月ごとの金利見直し」「5年ごとの返済額変更」「1.25倍ルール」の3点が頻出。「毎月金利が変わる・返済額がその都度変わる」は誤りの定番。変動金利型の低金利メリットと金利上昇リスクのトレードオフも理解する。",
    exp3: "「毎月金利見直し・毎月返済額変動」は誤り。金利見直し6か月・返済額変更5年・上限1.25倍の3点セットを確実に覚える。\n\n**覚え方:** 「変動金利＝6か月で金利チェック、5年で返済額変更、上限1.25倍の安全弁あり」。",
