    exp1: "固定金利型住宅ローンは、借入時に決定した金利が完済まで変わらない住宅ローン。フラット35が代表例。メリット：①返済計画が確定し家計管理が容易②市場金利が上昇しても返済額が増えない。デメリット：①市場金利低下の恩恵を受けられない②変動金利型より当初金利が高い場合が多い。金利低下局面での対応は繰上返済・借り換えで行う。",
    exp2: "試験では「全期間固定で返済額不変」「金利低下時に自動引下げなし（借り換えが必要）」「フラット35が固定金利型の代表」が問われる。「固定金利でも市場低下で自動引下げ」は誤りの定番。変動金利・固定金利・固定期間選択型（一定期間のみ固定）の3種類の区別も整理する。",
    exp3: "「市場金利低下で自動引下げ」は誤り。固定金利型は全期間固定。金利の恩恵を受けたい場合は借り換えや繰上返済を検討する必要がある。\n\n**覚え方:** 「固定金利＝全期間ロック。上がっても下がっても同じ返済額。安心だが低下の恩恵なし」。",
