    scenario: "不動産投資家の自分。融資が焦げ付いた物件の競売情報を裁判所の公告で見つけた。入札に参加したいが、通常の不動産購入とどう違うのかを整理しておきたい。",
    q: "次の状況に当てはまるのは？",
    choices: [{"text":"競売では裁判所が売却を行い、最高価格で入札した者が買受人となる","correct":true},{"text":"競売では売主（債務者）が価格を決定し、買主を選ぶことができる","correct":false,"hint":"競売は裁判所主導。売主に価格決定権はない。"}],
    exp1: "抵当権者等の申立てにより裁判所が債務者の不動産を強制的に売却する手続。最高価格で入札した者（最高価申出者）が買受人となり、売却代金が債権者への弁済に充てられる。売主の意思は不要。",
    exp2: "宅建試験では「任意売却との比較」で出題される。競売＝裁判所主導・売主関与なし・市場価格より20〜30%程度安くなりやすい。任意売却＝債権者同意のもと市場で売却・売主が手続きに関与・プライバシーが守られやすい。どちらも抵当権実行が背景にある点は共通だが、任意売却の方が売主・買主双方にとってメリットが大きいことが多い。→ t302 任意売却と対比して覚える。",
    exp3: "競売物件は内覧できないケースが多く、占有者がいる場合の明渡しリスクも買受人が負う。また物件の瑕疵も現況引渡しが原則で、契約不適合責任を問えない。「安い＝得」とは限らず、追加コストを含めた実質価格の計算が不可欠。3点セット（現況調査報告書・評価書・物件明細書）の読み込みが競売参加の必須スキル。\n\n**覚え方** 「競（きそ）って入れる＝競売」。裁判所が主役、売主は蚊帳の外。安い分だけリスクを自分で背負う。",
