    exp1: "区分所有マンションの維持・運営に関する実務。管理組合は区分所有法に基づき区分所有者全員で構成され、加入は強制。管理費（日常管理）と修繕積立金（将来の大規模修繕用）を月次で支払う義務がある。",
    exp2: "宅建試験では「管理組合の成立要件」「議決権・議事録」「管理者の権限」が出る。管理組合は区分所有者全員が構成員で法人化も可能（管理組合法人）。管理規約の設定・変更・廃止は区分所有者数および議決権の各4分の3以上の賛成が必要（特別決議）。集会は少なくとも年1回、管理者または区分所有者の5分の1以上の請求で招集される。→ t304 修繕積立金、t351 区分所有法とあわせて区分所有マンションの管理ルールを体系的に押さえる。",
