    exp1: "区分所有マンションにおいて、将来の外壁補修・屋上防水・エレベーター更新等の大規模修繕工事に備えて毎月積み立てる資金。管理組合が管理し、個人には返還されない（転売時は次のオーナーに引き継がれる）。",
    exp2: "宅建試験では「重要事項説明における説明事項」として出る。修繕積立金の額・積立状況・滞納状況は重要事項説明書（35条書面）への記載が必要。積立不足のマンションでは大規模修繕時に一時金徴収が発生するリスクがあり、買主にとって重大なリスク情報となる。国土交通省のガイドラインでは修繕積立金の目安として1㎡当たり月200〜250円程度が示されているが、実態は大幅に下回るマンションも多い。→ t305 長期修繕計画との連動も確認。",
