    exp1: "不動産会社（サブリース業者）がオーナーから物件を一括で借り上げ、入居者に転貸する賃貸管理の形態。オーナーは空室リスクを回避できるが、保証賃料は満室賃料より低く、定期的に見直される。入居者との直接契約はサブリース業者が行う。",
    exp2: "宅建試験では「特定賃貸借契約（サブリース契約）の規制」として出る。2021年6月施行の賃貸住宅管理業法により、サブリース業者は特定賃貸借契約締結前に書面を交付してオーナーへ重要事項説明が義務化。「家賃保証は永続しない」「借地借家法に基づく賃料減額請求ができる」点が頻出。また誇大広告（家賃が下がらないかのような表示）も禁止。→ t307 特定賃貸借契約・t385 賃貸住宅管理業者登録と合わせて管理業法の全体像を把握する。",
    exp3: "「家賃保証＝リスクゼロ」は誤解。10〜15年後に保証額が市場賃料の低下に伴って大幅減額され、解約もできないケースが問題化。借地借家法28条の「正当事由」なしでは業者側からの解約も難しく、オーナーが身動き取れなくなるケースも。契約前に「賃貸住宅管理業法上の重要事項説明」を受けることが義務。\n\n**覚え方** 「サブ（sub）＝下請け転貸」。業者がオーナーから借りて入居者に貸す。保証額は将来必ず見直される——永続保証はない。",
