    exp1: "サブリース契約の法的名称。賃貸住宅管理業法（2021年施行）により規制される。特定賃貸借契約の締結前に、①賃貸住宅管理業者が②書面を交付して③重要事項説明を行う義務がある。宅建業法の重要事項説明とは別の制度。",
    exp2: "宅建試験では「特定賃貸借契約の規制内容」として出る。説明義務の対象は「賃貸人（オーナー）」であり、借主ではない。書面の交付または電磁的方法による提供（オーナーの承諾が必要）も可。説明事項には①賃料・改定条件②契約期間③維持保全の内容④解除の条件等が含まれる。違反した場合は国土交通大臣による業務停止処分等の行政処分対象。誇大広告（「空室でも家賃100%保証」等の不実表示）も禁止。→ t306 サブリース・t308 賃貸管理業務と管理業法のセットで確認。",
    exp3: "「宅建業法の重要事項説明（35条）とは別物」が試験の核心。35条書面は買主・借主への説明。特定賃貸借の重要事項説明はオーナー（貸主）への説明。対象者・根拠法・内容がすべて異なる。宅建士でなくても説明できる（賃貸住宅管理業法上の要件は宅建士資格を求めていない）点も35条との違い。\n\n**覚え方** 「特定賃貸借＝サブリース」。オーナーへの説明が義務。宅建業法の35条（買主・借主向け）とは根拠法も対象者も別物。",
