    exp1: "賃貸住宅管理業法（2021年完全施行）により、管理戸数200戸以上の事業者は国土交通大臣への登録が義務化。登録事業者は管理受託契約締結前の重要事項説明・書面交付、業務の再委託制限、財産の分別管理等の義務を負う。",
    exp2: "宅建試験では「登録義務の戸数基準（200戸以上）」「管理受託契約の書面義務」「業務管理者の配置義務」が出る。200戸未満は登録任意（任意登録も可能で会員サービスを受けられる）。登録業者は管理受託契約の締結前に書面を交付して重要事項を説明しなければならず、各事務所に業務管理者（管理業務主任者等）を1名以上置く義務もある。登録の有効期間は5年（更新可）。→ t386 管理受託契約重要事項説明と連動して確認。",
    exp3: "宅建業免許と管理業登録は完全に別制度。宅建業免許があっても管理業登録なしに200戸以上を管理することはできない。逆に管理業登録だけでは売買・賃貸の仲介業務はできず、仲介を行うには宅建業免許も必要。2026年現在、賃貸住宅管理業者として国交大臣に登録している事業者は全国で約3,700社（増加傾向）。\n\n**覚え方** 「200戸以上の管理＝国交大臣登録義務」。宅建免許とは別。管理業は賃貸住宅管理業法で規制。200という数字で「二百（にひゃく）戸」と声に出して覚える。",
