    exp1: "賃貸借契約締結時に借主が貸主に支払う慣行上の金銭。謝礼的な性格を持ち、法律上の返還義務はない。敷金（担保・返還あり）とは異なり、貸主が当初から取得できる収入となる。関西では「敷引き」として機能が類似するケースもある。",
    exp2: "宅建試験では「敷金との違い」として出る。敷金＝担保・返還あり（通常損耗分は返還）、礼金＝慣行・返還義務なし。重要事項説明書（35条書面）の「金銭の授受」欄に礼金の額と性質（返還されない旨）の記載が必要。礼金ゼロ物件でも「敷金あり」の場合があり、また礼金の代わりに高めの家賃設定にしているケースもある。双方を区別して正確に説明する義務がある。→ t309 敷金と比較して金銭の性質の違いを整理。",
    exp3: "礼金は法律上の根拠がない慣行的な費用。近年（2020年代以降）は都市部でも礼金ゼロの物件が増えているが、試験では「礼金の法的性質＝返還義務なし」が問われる基本事項。関西地方では「敷引き」（敷金の一部を返還しない特約）が礼金と類似した機能を持つ慣行として存在し、一定の範囲で有効とされている点も併せて知っておく。\n\n**覚え方** 「礼金＝お礼なので返さない（法的義務なし）」。敷金は預け金で返ってくる。礼金は贈り物で返ってこない。近年ゼロが増えても法的性質は変わらない。",
