    exp1: "国土交通省が策定した「原状回復をめぐるトラブルとガイドライン」。退去時の原状回復費用の負担区分を明示。通常損耗（日常的な使用による損耗）・経年変化（時間経過による劣化）は貸主負担。借主の故意・過失・善管注意義務違反による損傷は借主負担。",
    exp2: "宅建試験では「原状回復の費用負担の原則」として出る。ガイドラインは法的拘束力はないが、裁判所の判断基準として参照され、多くの民事訴訟でガイドラインに基づく判断がなされている。特約で借主負担とする場合も、①必要性・合理性がある②借主が特約の内容を認識している③借主が特約に合意している、の3要件が満たされている必要がある。国交省ガイドラインは2011年に第3版が策定され、2026年現在も適用されている。→ t309 敷金と合わせて退去時の費用負担全体を整理。",
    exp3: "タバコのヤニによる汚れ・ペットによる傷・落書きは借主負担の典型例。壁紙の日焼け・フローリングの自然な傷みは貸主負担の典型例。どちらに該当するかが試験の核心。また経過年数の考慮も重要で、新品時の価値（1.0）から経年で残存価値が下がる（耐用年数6年のクロスなら6年経過で残存価値0.1）ため、借主負担分は経過年数を踏まえた減価後の価値で計算する。\n\n**覚え方** 「普通に使った分は貸主が払う」。借主が壊した分だけ借主負担。ヤニ・ペット・落書き＝借主、日焼け・自然劣化＝貸主と分類して覚える。",
