    q: "次の状況に当てはまるのは？",
    choices: [{"text":"不動産の証券化とは、不動産を裏付けとした有価証券を発行して投資家から資金調達する手法だ","correct":true},{"text":"不動産の証券化とは、不動産を現金化して分割売却することだ","correct":false,"hint":"証券化は有価証券発行による資金調達。現金分割売却とは異なる。"}],
    exp1: "特定目的会社（SPC）等を活用して不動産を流動化・証券化し、投資家から資金を集める手法。不動産投資信託（J-REIT）もその一形態。個人投資家が小口で不動産投資に参加できる仕組みを生み出した。流動性の低い不動産を証券という形で換金可能にする。",
    exp2: "宅建試験では「J-REITの仕組み」「不動産流動化」として出題される。J-REIT（不動産投資信託）は不動産を投資対象とする上場投資信託で、2001年に日本で初めて上場された。投資法人（会社型・主流）と投資信託（契約型）の2形態がある。2026年現在、東証に上場するJ-REITは約60銘柄（時価総額約16兆円）。個人投資家が少額（数万円から）で商業ビル・マンション・物流施設等の大型不動産に分散投資できる点が特徴。税・その他分野で出ることが多い。",
    exp3: "SPCと投資法人の違いが混乱ポイント。SPC（特別目的会社）は特定の不動産流動化のために設立する期間限定の法人。投資法人（REIT）は継続的に不動産を取得・運用する主体で永続性がある。目的・存続期間・投資家との関係がすべて異なる。不動産特定共同事業との混同にも注意。\n\n**覚え方** 「不動産を株のように細かく売る＝証券化」。J-REITはその代表例。SPC＝単発・特定案件向け、REIT＝継続運用・上場商品と区別する。",
