    exp1: "土地には複数の価格が存在する。①公示価格（国土交通省・毎年1月1日時点）を基準100とすると、②基準地標準価格（都道府県・7月1日時点）≒100、③路線価（国税庁・相続税・贈与税用）≒80%、④固定資産税評価額（市区町村・3年ごと）≒70%。",
    exp2: "宅建試験では「各価格の設定機関」「目的」「水準」を組み合わせた問題が出る。①公示価格（国土交通省・地価公示法・毎年1月1日基準・3月下旬公表）＝土地取引の指標・鑑定評価の規準。②基準地標準価格（都道府県・国土利用計画法・7月1日基準・9月下旬公表）。③路線価（国税庁・相続税・贈与税用）＝公示価格の80%水準。④固定資産税評価額（市区町村・3年ごと評価替え）＝公示価格の70%水準。→ t314 路線価・t315 固定資産税評価額と個別に詳細を確認。",
    exp3: "「公示価格は最も高い」という誤解がある。実際の市場価格（実勢価格）が公示価格を上回るケースも多く、特に都市部の人気エリアでは実勢価格が公示価格の130〜150%を超えることもある。公示価格は「適正な時価」の目安であり、市場価格と一致するとは限らない。また基準地標準価格と公示価格は基準日・公表時期は異なるが目的・水準はほぼ同じ（≒100）。\n\n**覚え方** 「公示100→路線価80→固定70」。高い順に：実勢＞公示≒基準地＞路線価（80%）＞固定資産税評価額（70%）。この比率を丸暗記して一気に整理。",
