    exp1: "住宅品質確保法に基づく任意制度。登録住宅性能評価機関（第三者機関）が住宅の性能を10分野（構造安定・劣化軽減・維持管理・温熱環境等）について評価し等級を表示する。設計段階（設計住宅性能評価書）と建設段階（建設住宅性能評価書）の2段階。",
