    exp1: "長期優良住宅の普及の促進に関する法律に基づく認定制度。耐震性・耐久性・維持管理のしやすさ・省エネ性等が一定基準を満たす住宅を所管行政庁（都道府県知事等）が認定する。任意の制度で、認定により住宅ローン控除・不動産取得税・登録免許税・固定資産税等で優遇を受けられる。",
