    exp1: "既存住宅（中古住宅）の売買に際して利用できる住宅瑕疵担保責任保険。引渡し後に構造耐力上主要な部分・雨水浸入防止部分等に瑕疵が発見された場合、補修費用等が保険から支払われる。国土交通大臣指定の保険法人（住宅保証機構等）が運営。",
    exp2: "宅建試験では「2018年宅建業法改正によるインスペクション説明義務の3段階」と「瑕疵保険の任意性」が出る。宅建業者の媒介時の義務：①媒介契約締結時にインスペクション業者のあっせんの可否を依頼者に明示②重要事項説明書（35条書面）に実施有無・結果を記載③37条書面（契約書）に建物の現況について当事者間で確認した内容を記載。いずれも「説明・記載義務」であり、インスペクション実施や瑕疵保険加入の強制ではない。→ t325 瑕疵保険と合わせて中古住宅の流通促進制度を整理。",
    exp3: "「インスペクションを実施した＝瑕疵保険に加入した」ではない。別の手続きが必要。インスペクションは「建物状況調査（現況確認）」、瑕疵保険は「欠陥発見時の補修費保証」。インスペクション合格物件のみ瑕疵保険に付保できる（保険会社が検査を要件とする）ため、順序としてはインスペクション→保険加入という流れになる。\n\n**覚え方** 「既存住宅瑕疵保険＝中古の欠陥リスクをカバー（任意）」。宅建業者はインスペクション説明義務あり（3段階：媒介契約・35条・37条）、保険加入義務なし。",
