    choices: [{"text":"宅建業者が依頼者（売主・買主）から不動産取引の仲介を受任する場合、媒介契約書の作成・交付が義務付けられている","correct":true},{"text":"口頭での媒介合意があれば書面を作成する義務はない","correct":false,"hint":"宅建業法34条の2により、売買・交換の媒介は書面の作成・交付が義務。"}],
    exp1: "宅建業者と依頼者（売主等）が締結する媒介・代理の委託契約。売買・交換の媒介契約は宅建業法34条の2に基づき書面（媒介契約書）の作成・交付が義務。記載事項は①物件を特定する情報、②売買すべき価額、③媒介契約の種類、④有効期間、⑤報酬額等。",
    exp2: "宅建試験では「媒介契約書の必要的記載事項」「3種類の媒介契約の違い」が頻出。一般媒介・専任媒介・専属専任媒介の3種類があり、違いは①複数業者への依頼可否②レインズ登録義務の有無③業務報告義務の有無④有効期間の上限の4点で整理する。賃貸借の媒介は宅建業法34条の2の書面義務の適用外であり、売買とは取り扱いが異なる。→ t361 一般媒介の義務・t362 契約期間の制限・t363 報告義務と体系的に確認。",
    exp3: "賃貸借の媒介には宅建業法34条の2の書面義務は適用されない（賃貸借の媒介契約書の義務規定はない）。試験で「賃貸の媒介にも書面が必要か」と問われたら「義務なし」と答える。なお実務上は賃貸媒介でも書面を作成することが多いが、あくまでも任意の実務慣行であり法的義務ではない点に注意する。\n\n**覚え方** 「売買の媒介は書面が必須（34条の2）・3種類から選ぶ。賃貸の媒介は書面義務なし」。賃貸と売買で義務の有無が違う重要な対比ポイント。",
