    q: "次の状況に当てはまるのは？",
    choices: [{"text":"宅建業者が代理として取引した場合の報酬限度額は、媒介の場合の2倍を上限とする","correct":true},{"text":"代理の場合も媒介と同じ報酬限度額が適用される","correct":false,"hint":"代理は媒介の2倍が上限。媒介と代理は異なる。"}],
    exp1: "宅建業者が本人（売主・買主等）の代理人として相手方と直接契約を締結する形態。媒介（仲介）は双方間の取引を補助するが、代理は本人に代わって法律行為そのものを行う。代理の場合の報酬限度額は媒介の2倍（ただし依頼者双方から受領する合計額が限度額以内）。",
    exp2: "宅建試験では「報酬限度額の計算」で代理が登場する。例：3000万円の売買で売主から代理を受任→媒介の場合の報酬限度額（3000万×3%＋6万）×1.1＝105.6万円、代理はその2倍で211.2万円が上限。ただし双方の代理人を兼ねる双方代理でも、売主・買主から受け取る合計額は媒介の2倍（211.2万円）が上限——片方ずつ2倍が認められるわけではない点に注意。→ t321 宅建業者間取引（業者間は報酬規制の適用外）と対比して理解。",
    exp3: "「代理だから双方からそれぞれ倍受け取れる」という誤解が多い。売主代理の場合は売主から媒介の2倍まで（買主からは別途媒介報酬の範囲内）受け取れるが、双方代理の場合の合計上限は「媒介報酬の2倍」。どちらのパターンかを問題文から正確に読み取ることが重要。\n\n**覚え方** 「代理の報酬上限＝媒介の2倍。双方代理でも合計は2倍まで（4倍にはならない）」。本人代わりに動く分、媒介より上限が高い。",
