    exp1: "宅地を複数区画に分割して販売する業態。宅建業（自ら売主として宅地を販売）に該当し、免許が必要。農地を宅地に転用する場合は農地法の許可が必要。造成工事が一定規模を超えると都市計画法の開発許可が必要（市街化区域1000㎡以上、三大都市圏特定区域500㎡以上）。",
    exp2: "宅建試験では「開発許可の要否」「農地転用許可の要否」を組み合わせた問題として出る。農地転用＋宅地造成＋分譲販売という一連の流れで複数の許可が重なる典型例。農地転用（農地法4条・5条）→宅地造成（都市計画法・開発許可：市街化区域1,000㎡以上等）→分譲販売（宅建業免許）と手続きが順番に積み重なる。三大都市圏の特定区域では市街化区域でも500㎡以上から開発許可が必要な点も押さえる。→ t349 開発許可の面積基準とあわせて各区域の基準を確認。",
    exp3: "宅地分譲は「宅建業免許＋開発許可（規模要件による）＋農地転用許可（農地の場合）」と複数の法規制が重なる。どれか一つでも欠くと違法となる。試験では各許可の有無を個別に判断させる設問が多く、「農地を宅地にして売る一連の行為」を複数法の視点でチェックする習慣が必要。また造成工事が完了した後も→ t398 造成完了検査（宅地造成等規制法）が必要なケースがある。\n\n**覚え方** 「宅地分譲＝宅建免許＋開発許可（1,000㎡以上）＋農地なら転用許可」。三つの壁を越えること。許可は農地法→開発許可→宅建業免許の順に積み上がる。",
