    exp1: "マンションを戸別に区分所有権として販売する業態。建設中に販売する「青田売り（未完成物件の売買）」では、宅建業法の厳しい規制が適用される。①手付金等の保全措置（代金の5%超または1000万円超の受領時）、②完成前の広告制限（開発許可等取得前の広告禁止）等が義務。",
    exp2: "宅建試験では「未完成物件の手付金保全措置の要件」が頻出。保全措置の3方法のうち、未完成物件で使えるのは①銀行等による連帯保証②保険事業者による保証保険の2方法のみ（③指定保管機関による保管は完成物件のみ可）。完成物件の保全義務発生基準（代金の10%超または1,000万円超）と未完成物件（5%超または1,000万円超）の違いをセットで覚える。「超」は10%・5%・1,000万円ジャストは含まない（超えた場合のみ義務）点も要注意。→ t372 手付金等の保全措置の方法・t373 完成物件の保全基準と一体的に整理。",
    exp3: "完成物件と未完成物件でパーセンテージが異なる。未完成＝5%超、完成＝10%超が保全措置発生基準。「厳しい規制＝未完成（工事中は物件が存在しないため買主のリスクが大きい）」という理由で覚えると忘れない。また保全措置は8種制限の一つであり、買主が宅建業者であれば不適用（業者間特則）。\n\n**覚え方** 「未完成＝5%超で保全措置。完成＝10%超で保全措置」。未完成の方が基準が厳しい（工事中で物件未確定のリスク分）。「未完成ミニ＝5%」と覚えると混乱しない。",
