    choices: [{"text":"専任宅建士に変更が生じた場合、変更の日から2週間以内に免許権者に届け出なければならない","correct":true},{"text":"専任宅建士の変更届は30日以内に行えばよい","correct":false,"hint":"期限は2週間以内。30日は誤り。"}],
    exp1: "宅建業者は専任宅建士に変更が生じた場合（退職・死亡・資格喪失等）、変更の日から2週間以内に免許権者（都道府県知事または国土交通大臣）に届け出る義務がある（宅建業法9条）。届出なしに「専任宅建士不足」の状態が続くと、業務停止処分の対象となる。",
    exp2: "宅建試験では「届出期限の数値」が問われる。変更届の2週間ルールは重要。また、専任宅建士の数が事務所の設置基準（5人に1人以上）を下回った場合は速やかに補充し、2週間以内に届け出が必要。人数不足のまま業務を続けると違反となる。",
    exp3: "「免許の変更届」は30日以内（商号・事務所・代表者等の変更）、「専任宅建士の変更届」は2週間以内、と期限が異なる。どちらの変更かで数値が変わる典型ひっかけ。\n\n**覚え方** 「専任宅建士の変更は2週間以内」。免許自体の変更は30日以内とは違う数字。",
