    q: "次の状況に当てはまるのは？",
    choices: [{"text":"婚姻により成年者と同一の行為能力を有する未成年者は、宅建士登録・宅建業免許の欠格事由に該当しない","correct":true},{"text":"未成年者は婚姻していても宅建士登録はできない","correct":false,"hint":"婚姻による成年擬制により行為能力が認められるため登録可能。"}],
    exp1: "民法上、婚姻した未成年者は成年者と同一の行為能力を有するとみなされる（成年擬制）。2022年民法改正で成年年齢が18歳に引き下げられたが、婚姻可能年齢も18歳となったため実務上の論点は変化している。宅建業法上は「成年者と同一の行為能力を有しない未成年者」が欠格事由であり、行為能力を有する（婚姻等）場合は該当しない。",
    exp2: "宅建試験では「欠格事由の該当可否」として出る。欠格事由に該当すると宅建士登録・宅建業免許の取得ができない。未成年者は原則として欠格事由だが、「成年者と同一の行為能力を有する場合」は除外される。",
    exp3: "2022年の民法改正（成年年齢18歳への引き下げ）により、18〜19歳は法律上成年となった。試験問題は改正後の法律ベースで出題されるため、「未成年者」の年齢定義に注意する。\n\n**覚え方** 「行為能力があれば未成年でも登録可能」。婚姻＝成年擬制＝欠格事由を抜ける。",
