    q: "次の状況に当てはまるのは？",
    choices: [{"text":"免許権者は宅建業者に免許を与える際、業務の適正な運営を確保するために必要な条件を付すことができる","correct":true},{"text":"免許に条件を付すことは法律上禁止されており、条件なしの免許のみが認められる","correct":false,"hint":"宅建業法3条3項で条件付き免許が認められている。"}],
    exp1: "宅建業法3条3項に基づき、免許権者（国土交通大臣または都道府県知事）は免許の付与に際して「業務の適正な運営を確保するために必要な限度において」条件を付すことができる。条件は業者の不利益にならない範囲で合理的なものに限られる。",
    exp2: "宅建試験では「免許の条件付与の可否」として出る。条件付き免許は法律上認められている。条件の内容例として「特定の業務形態に限定する」「定期的な報告義務を課す」等。条件に違反した場合は免許取消しの対象となる。",
    exp3: "「条件は業者の申請なしに付される」点を覚える。免許権者が一方的に判断して条件を付ける。業者が拒否することはできない（拒否すれば免許取得を断念するしかない）。\n\n**覚え方** 「免許に条件あり＝宅建業法で認められた制度」。業者は条件を受け入れるか、申請を取り下げるか。",
