    keyword: "区分所有法・集会決議or規約で選任・管理組合代表",
    scenario: "賃貸オーナーの自分。所有するマンションの管理組合で理事長（管理者）に選任された。「管理者にはどんな権限と義務があるのか」を整理したい。",
