    exp1: "管理者とは、区分所有法に基づいて管理組合を代表し、共用部分の管理・集会の招集・規約および集会の決議の実行を担う者。集会の決議または規約の定めにより選任・解任される。管理者は区分所有者以外（管理会社等）でもなれる。共用部分の変更・保存行為を実施し、管理組合を代表して外部との契約を締結する権限を持つ。",
    exp2: "試験では「管理者の選任方法」「管理者の権限と義務」が問われる。管理者の主な義務：①集会の招集（少なくとも年1回）②規約・集会議事録の保管③利害関係人への閲覧供与④区分所有者から報告を求められたときはいつでも報告。管理者が選任されていない場合は、区分所有者の5分の1以上（規約で減額可）の請求で集会を招集できる。不正行為をした管理者は集会の普通決議で解任できる（全員同意は不要）。管理者の権限：外部との契約締結・共用部分の管理・訴訟における管理組合代表。→ t351 区分所有法の集会の決議要件・t354 議決権とあわせて意思決定の全体像を確認。",
    exp3: "「管理者＝区分所有者に限る」は誤り。外部の管理会社が管理者となることも多い（第三者管理方式、2023年改正で法的整備が進んだ）。また「管理者がいなければ管理組合が成立しない」も誤りで、管理者の選任は義務ではなく任意。管理者不在の場合は区分所有者各自が保存行為を単独で実施できる（保存行為は決議不要）。\n\n**覚え方** 「管理者＝管理組合の代表（社長）。選任は集会の普通決議か規約——全員同意は不要」。区分所有者以外（管理会社等）がなれる点も重要。",
