    exp1: "議決権とは、管理組合の集会において区分所有者が行使できる意思決定の権利。区分所有法上の原則は、専有部分の床面積の割合によって議決権の割合が決まる。ただし規約で別段の定め（1戸1票制等）も可能。集会での決議は「区分所有者数の要件」と「議決権の要件」の両方を満たす必要がある（例：特別決議は区分所有者数・議決権ともに4分の3以上）。",
    exp2: "試験では「普通決議・特別決議・建替え決議の要件」が必出。普通決議：区分所有者数および議決権の各過半数（1/2超）。特別決議（規約設定・変更・廃止、共用部分の重大変更等）：区分所有者数および議決権の各4分の3以上。建替え決議：区分所有者数および議決権の各5分の4以上（より高いハードル）。決議要件の数値は「普通→過半数→3/4→4/5」と重大なほど高くなる段階構造で覚える。→ t355 滅失の場合の復旧（大規模滅失＝4/3）とあわせて決議要件を完全整理。",
    exp3: "「区分所有者数」と「議決権」は別々にカウントする。複数室所有者は区分所有者数では1人だが、議決権は複数室分の床面積割合を合算した値になる。この違いを混同すると計算問題で失点する。規約で1戸1票制を採用している場合は規約が優先され、議決権の計算が変わる（1室でも3室でも1票）。また集会に出席しない区分所有者について、書面・代理人による議決権行使も認められる。\n\n**覚え方** 「議決権の原則＝床面積割合。人数カウントとは別——1人で3部屋持てば議決権は3倍、でも区分所有者数の頭数は1人」。区分所有者数と議決権は別々に数えて両方の要件を満たす必要がある。",
