    exp1: "区分所有法上、建物が滅失した場合の復旧決議の要件は滅失の規模によって異なる。建物価格の2分の1以下の滅失（小規模滅失）：集会の普通決議（過半数）または各区分所有者が単独で復旧可能。建物価格の2分の1を超える滅失（大規模滅失）：集会の特別決議（区分所有者数および議決権の各4分の3以上）が必要。",
    exp2: "試験では「大規模か小規模かの判断基準（建物価格の1/2が分岐点）」と「それぞれの決議要件」が問われる。大規模滅失の場合、復旧決議から2週間以内に「復旧決議に反対した区分所有者」は賛成した区分所有者に対して時価での区分所有権・敷地利用権の買取を請求できる（買取請求権）。この買取請求権は大規模滅失の復旧決議固有のルールで、反対者が「自分だけ抜けたい」場合に使える権利。建替え決議（5/4以上）とは混同しないこと——建替えでは賛成者が反対者に対して「売渡し請求」を行う逆の構造。→ t354 議決権の決議要件との比較で数値を整理。",
    exp3: "「大規模滅失＝過半数でOK」は誤り。大規模滅失（建物価格の1/2超）の復旧には4分の3以上の特別決議が必要。小規模滅失（1/2以下）は普通決議（過半数）または各区分所有者単独での復旧が可能。建替え決議（5/4以上）との混同も典型ミス——「復旧＝4/3、建替え＝5/4（より厳しい）」と数値の大小で区別する。\n\n**覚え方** 「滅失の境界は建物価格の1/2——超えたら4分の3の特別決議。建替えはさらに厳しく5分の4」。1/2超→大規模→4/3の決議、建替え→5/4の決議と段階を上げて覚える。",
