    scenario: "自宅売却を検討する60代の自分。不動産業者と専任媒介契約を締結した。「どのくらいの頻度で売却活動の報告を受けられるのか」を確認したい。",
    q: "次の状況に当てはまるのは？",
    choices: [{"text":"専任媒介契約では2週間に1回以上、専属専任媒介契約では1週間に1回以上の業務報告が義務付けられている","correct":true},{"text":"専任媒介契約・専属専任媒介契約ともに1か月に1回以上の業務報告で足りる","correct":false,"hint":"1か月は誤り。専任は2週間、専属専任は1週間が正しい。"}],
    exp1: "宅建業者は専任媒介・専属専任媒介契約を締結した場合、依頼者に対して定期的に業務の処理状況を報告する義務を負う。専任媒介契約：2週間に1回以上。専属専任媒介契約：1週間に1回以上（より高い報告頻度）。報告方法は書面（または電磁的方法）で行う。一般媒介契約には業務報告義務の規定がない。",
    exp2: "試験では「専任2週間・専属専任1週間」という数字の対比が必出。専属専任の方が依頼者（売主）への拘束が強い分（自己発見取引も禁止・業者1社のみに全権委任）、業者の報告義務も重くなっている点は制度上の対応関係として合理的に理解できる。報告義務の内容は「業務の処理状況の報告」であり、レインズへの登録状況・問い合わせ件数・内覧状況・価格交渉の有無等が含まれる。報告方法は書面（電磁的方法でも可）。報告を怠った場合は宅建業法違反として指示処分の対象。→ t364 レインズ登録義務（専任7日・専属専任5日）と数字をセットで覚える。",
    exp3: "「一般媒介にも報告義務がある」は誤り。報告義務は専任系（専任・専属専任）媒介のみ。専任と専属専任の数字（2週間・1週間）は逆に覚えないよう注意——専属専任の方が頻度が高い（1週間）、専任は隔週（2週間）。レインズ登録義務の日数（専任7日・専属専任5日）と合わせて「専属専任は短い数字・頻繁」と覚えると混乱しない。\n\n**覚え方** 「専任＝2週に1回（隔週報告）、専属専任＝1週に1回（毎週報告）——専属は週報、専任は隔週報告。一般は報告義務なし」。",
