    scenario: "不動産営業マンの自分。売主と専属専任媒介契約を締結した翌日、上司から「レインズへの登録を早くしろ」と言われた。契約締結から何日以内に登録しなければならないか確認する。",
    q: "次の状況に当てはまるのは？",
    choices: [{"text":"専属専任媒介契約では契約締結の日から5日以内（休業日除く）に指定流通機構へ登録しなければならない","correct":true},{"text":"専属専任媒介契約では契約締結の日から7日以内に指定流通機構へ登録しなければならない","correct":false,"hint":"7日は専任媒介の登録期限。専属専任は5日以内（より短い）。"}],
    exp1: "宅建業者は専任媒介・専属専任媒介契約を締結したとき、指定流通機構（レインズ）に物件情報を登録する義務を負う。登録期限は専任媒介：契約締結日の翌日から7日以内（休業日除く）。専属専任媒介：契約締結日の翌日から5日以内（休業日除く）。一般媒介契約にはレインズへの登録義務がない。登録後は依頼者（売主）に登録証明書を交付しなければならない。",
    exp2: "試験では「専任7日・専属専任5日」という数字の対比が頻出。期限のカウントは「契約締結日の翌日」から起算し、休業日を除く（土日祝が休業日の場合はその分加算）。レインズへの登録義務は「売買・交換の専任系媒介」に限られ、賃貸の媒介には登録義務がない。登録後は依頼者（売主）に登録証明書を遅滞なく交付する義務がある（「登録した」という口頭報告だけはNG）。成約後は成約情報のレインズへの登録（成約報告義務）も別途義務付けられている。→ t363 取引状況の報告義務（専任2週・専属1週）と合わせて「専任系媒介の義務一覧」を整理。",
    exp3: "「専属専任7日・専任5日」と逆に覚えないよう注意——専属専任の方が登録期限が短い（厳しい・早く登録しなければならない）。「専属＝5日（より短く・より早く登録）・専任＝7日」と方向性で覚える。また賃貸媒介にはレインズ登録義務なし、という点も落とし穴になる。一般媒介も登録義務なし。\n\n**覚え方** 「専属＝5日（5文字・5日）、専任＝7日（7文字・7日）」と字数で覚えると間違えにくい。専属の方が厳しく5日（早め）、専任は7日。賃貸と一般媒介は登録義務なし。",
