    exp1: "宅建業者が自ら売主となる未完成物件（建築工事完了前の宅地・建物）の売買において、手付金等として受領する額が「売買代金の5%超」または「1000万円超」のいずれかを超える場合に保全措置が義務付けられる。上記の例（代金4000万円・内金150万円）：150万円÷4000万円＝3.75%で5%未満、かつ150万円は1000万円以下→保全措置不要。",
    exp2: "試験では「完成物件10%超・未完成物件5%超（いずれも1,000万円超も対象）」の違いをしっかり覚えたうえで計算問題を解く。未完成物件での計算例：①代金3,000万円・手付金200万円→200÷3,000≒6.7%で5%超→保全必要。②代金4,000万円・内金150万円→3.75%で5%未満かつ1,000万円以下→保全不要。未完成物件の保全方法は①銀行保証②保証保険の2方法のみ（指定保管機関による保管は不可）。→ t373 完成物件の保全基準（10%・1,000万円・3方法）と比較して違いを確認。",
    exp3: "「手付金等」には手付金だけでなく内金・中間金等、引渡し前に受け取るすべての金銭が含まれる。複数回に分けて受け取る場合は各回の累計額で判断する——初回が5%未満でも2回目との累計が5%超になれば保全義務が発生する。5%超・1,000万円超のどちらか一方でも「超えれば」保全必要——「かつ」ではなく「または」が正しい理解。「超」はジャスト（5%ちょうど・1,000万円ちょうど）を含まない点も要注意。\n\n**覚え方** 「未完成は5%超（厳しめ）・完成は10%超（ゆるめ）——どちらも1,000万円超でも保全義務（または条件）」。未完成は保管機関使えない（2択）も一緒に覚える。",
