    cat: "業法",
    freq: "mid",
    diff: "mid",
    keyword: "昭和56年5月31日以前の建物・耐震診断結果を35条書面に記載",
    scenario: "不動産営業マンの自分。昭和52年築の中古一戸建ての売買仲介をしている。買主への重要事項説明で耐震診断に関する説明が必要かどうか確認する。",
    q: "次の状況に当てはまるのは？",
    choices: [{"text":"昭和56年5月31日以前に新築工事に着手した既存建物については、耐震診断の有無・内容を35条書面に記載しなければならない","correct":true},{"text":"耐震診断は全ての既存建物について35条書面への記載が必要である","correct":false,"hint":"耐震診断の記載義務は昭和56年5月31日以前に着工した建物に限定される（旧耐震基準の建物）。"}],
    exp1: "宅建業法35条の重要事項説明において、「耐震診断の内容」は昭和56年5月31日以前に新築工事に着手した建物（旧耐震基準の建物）の売買・交換の場合に説明義務がある。昭和56年6月1日以降着工の建物（新耐震基準）は対象外。耐震診断が実施されていない場合はその旨（「未実施」）を説明すれば足りる（業者が診断を行う義務はない）。",
    exp2: "試験では「昭和56年5月31日以前着工（旧耐震基準）という基準日」と「説明義務の内容」が問われる。昭和56年6月1日施行の改正建築基準法から新耐震基準が適用されたため、それ以前に着工した建物は旧耐震基準（大規模地震への耐力が新耐震基準より低い可能性がある）。耐震診断が実施されている場合はその結果の概要（適合・不適合・補強が必要等）を35条書面に記載して説明する義務がある。実施されていない場合は「未実施」の旨を記載・説明すれば足りる。なお住宅ローンの利用可否・保険料にも耐震性能が影響するため、買主への重要情報。→ t376 石綿使用調査（同様に記録有無の確認・未実施の場合は旨を説明）と共通点を確認。",
    exp3: "「昭和56年6月1日以降着工の建物は説明不要」は正しい（新耐震基準適用のため対象外）。「昭和56年5月31日以前着工」と「以降着工」の境界線を問題文から正確に読み取ることが重要。アスベスト調査と同様、業者に独自の耐震診断実施義務はなく、「記録がなければ未実施の旨を説明」で足りる点も共通している。また賃貸の場合も同様に耐震診断の有無・結果を35条書面に記載する義務がある。\n\n**覚え方** 「昭和56年6月1日＝新耐震基準スタート。それ以前（5月31日以前）着工の建物が耐震診断説明の対象」。56年6月1日の前後で扱いが変わる重要な分岐点。未実施なら「未実施と書く」だけでOK。",
