    scenario: "不動産営業マンの自分。建築後14か月・一度も入居者のいない戸建住宅の広告を作成している。「新築」と表示してよいか確認する必要がある。",
    q: "次の状況に当てはまるのは？",
    choices: [{"text":"「新築」と表示できるのは建築後1年未満かつ未使用の住宅に限られる","correct":true},{"text":"一度も使用されていない住宅であれば建築後の経過年数にかかわらず「新築」と表示できる","correct":false,"hint":"未使用であっても建築後1年以上経過した住宅は「新築」と表示できない。1年未満かつ未使用の両方が必要。"}],
    exp1: "不動産の公正競争規約は、「新築」という表示を「建築後1年未満であって、居住の用に供されたことがないもの」に限定している。つまり建築後1年未満（期間要件）かつ未使用（使用実績なし）の両方を満たす場合のみ「新築」と表示できる。上記の例（建築後14か月・未使用）は期間要件を満たさないため「新築」と表示不可。",
    exp2: "試験では「1年未満かつ未使用」という2つの要件が必出。どちらか一方でも欠ければ「新築」とは表示できない。建築後1年以上の未使用住宅は「未入居物件」「未使用住宅」等と表示することになる。この規定は不動産広告の公正競争規約（全国宅地建物取引業協会連合会等が定める自主規制）に基づくもので、景品表示法の特例として認定されている。",
    exp3: "「一度も住んでいないから新築」は誤り（1年以上経過は不可）。「建て売り住宅が1年以上売れ残っても新築」は誤り。宅建試験では「1年未満かつ未使用」という両要件を即答できるようにする。徒歩の表示（80m1分）・新築の表示（1年未満・未使用）は公正競争規約の頻出ペアとして一緒に覚える。\n\n**覚え方** 「新築の条件＝1年未満＋未使用の両方。片方だけではNG——1年過ぎたら未使用でも新築と言えない」。",
