    keyword: "80mを1分として計算・端数は切り上げ",
    scenario: "不動産営業マンの自分。最寄り駅から物件まで実際に歩いたら11分かかった。広告の徒歩表示は何分と記載すべきか確認する。",
    q: "次の状況に当てはまるのは？",
    choices: [{"text":"徒歩所要時間は道路距離80mを1分として計算し、1分未満の端数は切り上げる","correct":true},{"text":"徒歩所要時間は道路距離100mを1分として計算する","correct":false,"hint":"100mではなく80m。80m＝1分が公正競争規約の定める計算方法。"}],
    exp1: "不動産の公正競争規約は、徒歩による所要時間の表示について「道路距離80mにつき1分を要するものとして算出した数値を表示し、1分未満の端数が生じた場合は1分として表示する」と定めている。例：駅から物件まで道路距離880m→880m÷80m＝11分ちょうど→11分と表示。",
    exp2: "試験では「80m＝1分・端数は切り上げ」という計算ルールが問われる。計算例：700m÷80m＝8.75分→端数切り上げで9分と表示。また信号待ち・坂道・交差点の待機時間等は考慮しない（道路距離のみで機械的に計算）。「実際に歩いたら12分だったのに10分表示」という広告は過少表示として問題になりうる。徒歩表示の起点は「鉄道の駅その他の施設の出入口」から物件の「入口」まで。",
    exp3: "「端数切り捨て」は誤り——端数は必ず切り上げ（1分として表示）。「100m＝1分」は誤り——正しくは80m。この数字は試験で頻繁に出るため確実に覚える。新築の表示（1年未満・未使用）と並んで公正競争規約の2大頻出ポイント。\n\n**覚え方** 「徒歩1分＝80m（はちじゅうメートル）——100mではなく80m。端数は切り上げ必須」。",
