    q: "次の状況に当てはまるのは？",
    choices: [{"text":"管理戸数が200戸以上の賃貸住宅管理業者は国土交通大臣への登録が義務付けられている","correct":true},{"text":"賃貸住宅管理業者の登録は任意であり、すべての業者が自由に登録できる","correct":false,"hint":"200戸以上を管理する業者への登録は義務（強制）。任意ではない。"}],
    exp1: "賃貸住宅の管理業務等の適正化に関する法律（2021年6月施行）により、管理戸数200戸以上の賃貸住宅管理業者は国土交通大臣への登録が義務付けられた。登録業者は①管理受託契約前の重要事項説明②管理受託契約締結時の書面交付③財産の分別管理④業務状況の報告等の義務を負う。200戸未満は任意登録（登録することは可能）。",
    exp2: "試験では「200戸以上＝義務・200戸未満＝任意」という基準と、登録業者の主な義務が問われる。重要事項説明の対象はオーナー（委託者）であり、借主ではない点に注意。業務管理者（管理業務主任者等）の事務所ごとの設置義務もある。登録の有効期間は5年（更新可）。",
    exp3: "「賃貸管理業者登録と宅建業免許は別物」であることに注意。宅建業者が媒介（仲介）を行うには宅建業免許が必要だが、管理業務を行うには（200戸以上なら）賃貸住宅管理業者登録が必要。両方の登録・免許を持つ会社も多いが制度は別々。\n\n**覚え方** 「200戸以上の管理業者は登録義務——「二百」で覚える。200未満は任意」。",
