    q: "次の状況に当てはまるのは？",
    choices: [{"text":"維持保全とは、賃貸住宅管理業者が行う建物・設備の点検・清掃・修繕等の管理業務である","correct":true},{"text":"維持保全とは、賃貸住宅の入居者募集・仲介業務のことである","correct":false,"hint":"入居者募集・仲介は宅建業（仲介）の業務。維持保全は建物・設備の物的管理を指す。"}],
    exp1: "賃貸住宅管理業における「維持保全」とは、賃貸住宅の建物・設備について、①点検・清掃・補修等を一体として行う業務（維持保全業務）を指す。具体的には共用部の清掃・設備点検・修繕対応・緊急時の対応等が含まれる。維持保全業務は管理業者が自ら行う場合と、外部業者に再委託する場合がある（再委託先への監督義務あり）。",
    exp2: "試験では「維持保全の定義」と「再委託の可否」が問われる。賃貸住宅管理業者は維持保全業務の全部を第三者に再委託してはならない（一部の再委託は可能）。また維持保全業務と賃貸借契約の更新・解約等の「入居者管理業務」は異なる概念として整理する。賃貸住宅管理業法上の「管理業務」には維持保全だけでなく、家賃等の徴収・入居者への通知等も含まれる。",
    exp3: "「維持保全の全部を再委託できる」は誤り。全部再委託は禁止。一部再委託は可。管理業者がオーナーに代わって建物を適切に維持することが維持保全の本質であり、形式的な業者登録だけで実質業務をすべて外出しすることは制度の趣旨に反する。\n\n**覚え方** 「維持保全＝建物・設備の点検・修繕等の物的管理業務——仲介や家賃管理とは別の概念」。",
