    exp1: "日本の住宅流通市場を新築偏重から既存住宅（中古住宅）取引へ転換するため、2018年に宅建業法が改正され、媒介契約時の建物状況調査（インスペクション）の斡旋可否の説明義務、重要事項説明での調査結果の説明義務、37条書面での建物の現況合意の記載義務が新設された。また既存住宅売買瑕疵保険の普及も促進されている。",
    exp2: "試験では「インスペクション（建物状況調査）に関する宅建業者の義務」が問われる。宅建業者が媒介契約を締結する際に依頼者に対して「建物状況調査を実施する者のあっせんの有無」を明示する義務がある（強制ではなくあっせんの可否を説明するだけ）。重要事項説明での調査結果の提供義務（実施済みの場合）、37条書面での現況確認の記載義務も合わせて押さえる。",
