    exp1: "住宅履歴情報（通称「いえかるて」）とは、住宅の設計図書・施工状況・定期点検・修繕・リフォームの記録などを竣工時から継続して蓄積・管理する仕組み。国土交通省が推進する既存住宅流通促進策の一環として整備されており、履歴情報が整っている物件は品質の透明性が高く、適正な価格評価や購入者の安心感につながる。",
    exp2: "試験では「住宅履歴情報の目的と内容」が問われる。履歴情報を活用することで①売却時の価格交渉で有利②リフォーム業者が適切な工事計画を立てやすい③将来の修繕計画の策定に役立つ——などのメリットがある。住宅履歴情報の整備は義務ではないが、長期優良住宅の認定要件の一つとして維持保全計画の作成・実施記録の保存が求められている。",
    exp3: "「住宅履歴情報の保存は法律で義務付けられている」は誤り（長期優良住宅等の特定の場合を除く）。一般的な住宅では任意。ただし整備されている物件の方が既存住宅市場での評価が高まる傾向がある。インスペクション（建物状況調査）・既存住宅売買瑕疵保険とセットで「既存住宅の品質見える化」の制度として位置づけられる。\n\n**覚え方** 「住宅履歴情報＝建物の履歴書（いえかるて）——設計から修繕まで記録を残して既存住宅の透明性を高める」。",
