    choices: [{"text":"市街化調整区域では原則として建築物の建築（自己用住宅も含む）には開発許可または建築許可が必要となる","correct":true},{"text":"市街化調整区域でも自己用住宅なら開発許可なしに自由に建築できる","correct":false,"hint":"市街化調整区域は市街化を抑制する区域であり、自己用住宅であっても原則として開発許可・建築許可が必要。"}],
    exp1: "市街化調整区域とは、都市計画法により市街化を抑制すべき区域として指定された区域。この区域では建築物の建築・土地の区画形質の変更（開発行為）は原則として都道府県知事等の開発許可・建築許可が必要となる。農家の住宅・日常生活に必要な施設等の例外はあるが、一般的な自己用住宅の建築は原則として許可が必要。",
    exp2: "試験では「市街化調整区域の建築制限の原則と例外」が問われる。開発許可不要の例外（主なもの）：①農業・林業・漁業用の建築物（農家住宅含む）②公益上必要な建築物（駅・公民館等）③市街化区域に隣接等の区域における小規模開発（規模の要件あり）④既存建築物の建替え（同一用途・規模の範囲内）。これらの例外に該当しない場合は原則として許可が必要。",
    exp3: "「市街化調整区域でも一般の自己用住宅が建てられる」は誤り（原則禁止・例外あり）。農家の二世帯住宅（分家住宅）等も例外として認められる場合があるが、許可が必要。宅建の現場でも「市街化調整区域の土地を買ったが建物が建てられない」というトラブルが多く、重要事項説明での告知が不可欠。\n\n**覚え方** 「市街化調整区域＝原則建築NG——市街化を「調整（抑制）」する区域だから建物が原則建てられない」。",
