    q: "次の状況に当てはまるのは？",
    choices: [{"text":"都市計画区域において市街化区域と市街化調整区域に区分することを「線引き」といい、この区域区分は都市計画決定によって定められる","correct":true},{"text":"区域区分は都道府県知事が単独で決定でき、都市計画決定は不要である","correct":false,"hint":"区域区分は都市計画決定によって定める必要がある。都道府県が都市計画として決定する。"}],
    exp1: "都市計画区域内を「市街化区域」と「市街化調整区域」に区分することを「区域区分」または「線引き」という。区域区分は都市計画法による都市計画として都道府県が定める（大都市圏等では義務、その他は任意）。区域区分が行われていない都市計画区域を「非線引き区域」という。区域区分を行うかどうかは都市計画の一部であり、都市計画審議会の審議・国土交通大臣との協議等を経て決定される。",
    exp2: "試験では「線引き都市計画区域・非線引き都市計画区域・都市計画区域外の3区分」と各区域での開発許可基準の違いが問われる。市街化区域：積極的に市街化を促進する区域（用途地域が必ず定められる）。市街化調整区域：市街化を抑制する区域（用途地域は原則定めない）。非線引き区域：区域区分がなく両区域の制限が混在する中間的な区域。",
    exp3: "「線引きは市町村が決める」は誤り。原則は都道府県が決定。また「すべての都市計画区域に線引きがある」も誤り——任意で線引きをしない非線引き区域も存在する。農地法・開発許可・建築基準法の規制が「どの区域か」によって異なる点が宅建試験の重要テーマ。\n\n**覚え方** 「線引き＝都市計画で市街化区域と市街化調整区域に分けること——都道府県が都市計画として決定」。",
