    exp1: "果実とは物から生じる収益のこと。「天然果実」は物の用法に従い収取する産出物（農産物・鉱産物・家畜の子等）で、分離時に収取権を持つ者が取得する。「法定果実」は法律関係（賃貸借契約・利息等）から生じる収益（賃料・利息等）で、収取権を持つ期間に対応して日割り計算で取得する。",
    exp2: "抵当権との関係で出題される（→t410・t418参照）。抵当権は債務不履行前の法定果実（賃料）には原則として及ばない。債務不履行後は担保不動産収益執行の申立てにより賃料に及ぶ（民事執行法180条2号）。また売買代金の精算（賃料の日割り清算）でも天然果実・法定果実の区別が実務上重要。天然果実の取得権：「分離時に収取権を持つ者が取得」→売買では引渡し前に収穫済みの農産物は売主に帰属。法定果実の取得権：「収取権を持つ期間に対応して日割り計算」→月の途中に所有権が移転した場合は日割りで按分する。",
    exp3: "天然果実は「分離時」が基準、法定果実は「日割り」が基準。この時間的な取得基準の違いが試験のポイント。「木から落ちたリンゴは天然果実か法定果実か」→天然果実（物の産出物）。賃料・利息は法定果実（法律関係から生じる収益）。従物（→t411参照）との区別として、果実は主物から収益として「生まれてくる」もの・従物は主物とは別に「すでに存在する」もの、という構造の違いを理解しておく。\n\n**覚え方** 「自然にできる実＝天然果実、法律関係から生まれる実＝法定果実」。賃料・利息は法定。分離時 vs 日割りという取得基準の差が試験のカギ。",
