    exp1: "土地区画整理組合は、施行区域内の宅地所有者・借地権者7人以上が設立し、都道府県知事の認可を受けて成立する。組合設立の認可後、区域内の全宅地所有者・借地権者は自動的に組合員となる（強制加入）。組合は換地計画・資金計画を定め、事業を推進する。",
    exp2: "「設立要件」が試験頻出。区域内の宅地所有者および借地権者のそれぞれ3分の2以上の同意が必要（土地区画整理法18条）。同意は人数基準と地積（面積）基準の両方を満たすことが必要（宅地所有者の3分の2以上かつその所有地積の3分の2以上、借地権者の3分の2以上かつその借地の3分の2以上）。総会では事業計画変更・換地計画・賦課金決定等の重要議決を行う。組合の解散は事業完了後に総会の議決で行い、都道府県知事の認可が必要。",
    exp3: "組合員は賦課金・分担金の納付義務を負う。滞納の場合は強制徴収（地方税の例による）も可能（→t419参照）。組合は法人格を持ち、施行者として換地処分権限を持つ。「組合員でなければ施行区域内の土地は持てない」とは異なり、非組合員の土地所有者もいる（公共用地・施行者保留地等）。組合設立認可後に施行区域内で宅地を取得した者も自動的に組合員になる。\n\n**覚え方** 「3分の2の同意で設立、認可後は全員強制加入＝区画整理組合」。同意は人数×地積の両方が3分の2以上と覚える。",
