    exp1: "市街地開発事業とは、都市計画法で定める面的整備事業の総称で、①土地区画整理事業②市街地再開発事業③住宅街区整備事業④防災街区整備事業⑤新住宅市街地開発事業⑥工業団地造成事業等が含まれる（都市計画法12条）。都市計画区域内の一定区域について、都市計画として決定される。",
    exp2: "「市街地再開発事業との違い」が試験で問われる。市街地再開発事業は老朽化した建物密集地を高度利用（高層化）して整備する事業で、「権利変換方式」（従前の権利を新たなビルの床権利に変換）が特徴。土地区画整理事業（→t421参照）は「換地方式」で宅地の整形・道路・公園の整備が目的。都市計画法12条に列挙される市街地開発事業の6種類（①土地区画整理事業②市街地再開発事業③住宅街区整備事業④防災街区整備事業⑤新住宅市街地開発事業⑥工業団地造成事業）を覚える。特に①と②の違いを問う問題が頻出。",
    exp3: "市街地開発事業の都市計画決定後は、事業予定区域内で建築制限がかかる（都市計画施設予定地（→t423参照）と同様）。面的整備事業であるため、区域内の全土地所有者・借地権者に影響が及ぶ点が個別の建築確認と異なる。重要事項説明（→t470参照）では施行中の区画整理・再開発事業の有無を法令制限の概要として説明する義務がある。\n\n**覚え方** 「面的整備の総称＝市街地開発事業」。区画整理も再開発もどちらも含む。6種類の中では①区画整理と②市街地再開発の違い（換地方式 vs 権利変換方式）を押さえる。",
