    exp2: "地区計画の構成が試験で問われる。地区計画は「地区整備計画」（詳細な建築ルール：建築物の用途制限・容積率・建蔽率・高さ・壁面の位置等）を定めるのが基本で、その中に再開発等促進区・開発整備促進区を定めることができる。地区計画は都市計画区域内（一定の条件下では準都市計画区域内も可）の一定区域に定められ、区域内の建築に細かい制限をかける。再開発等促進区を定めた場合は通常の用途地域の容積率を超えた容積率を定めることができ、これにより高密度な開発が可能になる。開発許可の特例（地区計画適合の場合は開発許可不要になる場合あり）も確認。",
    exp3: "再開発等促進区は特定街区（都市計画として別途定める街区・高容積率を認める）と混同しやすい。特定街区は「都市計画として単独で定める」街区。再開発等促進区は「地区計画の中の区域」という位置づけ。「地区計画の中にある＝再開発等促進区」と整理する。市街地開発事業（→t424参照）・都市計画施設（→t423参照）との組み合わせで活用されることが多い。\n\n**覚え方** 「地区計画の中で容積率特例を使えるエリア＝再開発等促進区」。特定街区とは別物（特定街区は単独の都市計画）。",
