    q: "次の状況に当てはまるのは？",
    choices: [{"text":"建築基準法は建築物の最低基準を定めた法律であり、これを上回る基準で建築することは自由","correct":true},{"text":"建築基準法の基準が最高基準であり、それ以上の仕様で建てることは認められない","correct":false,"hint":"最低基準なので、上回ることは自由。法律の目的・性格の理解が問われる。"}],
    exp1: "建築基準法は、建築物の敷地・構造・設備・用途に関する最低基準を定め、国民の生命・健康・財産の保護を図ることを目的とする（建築基準法1条）。最低基準であるため、施主や設計者がより高い基準で建築することは制限されない。建築確認制度・完了検査制度もこの法律の重要な柱。",
    exp2: "「単体規定と集団規定の区別」が試験の核心。単体規定（→t431参照）は全国一律に適用（構造・採光・換気・防火・避難等）。集団規定（→t432参照）は都市計画区域・準都市計画区域内のみ適用（用途地域・建蔽率・容積率・道路斜線・日影規制等）。適用区域の違いを混同させるひっかけが多い。建築基準法の対象は「建築物（土地に定着する工作物で屋根・柱・壁を有するもの）」で、これに付属する設備・用途も規制対象。2006年改正で建築確認・検査の厳格化が行われ、指定確認検査機関（→t427参照）の活用が本格化した。",
    exp3: "建築基準法は「最低基準」であることを意識する。試験で「建築基準法の基準を満たしていれば何でも建てられる」という選択肢は正しいが、「建築基準法を守れば最高品質の建物ができる」は誤り。最低基準＝床・下限であって最高・上限ではない。既存不適格建築物（建築時は合法だが法改正で現行基準に不適合となった建物）は「すぐに違法になる」わけではなく、増改築時に現行基準への適合が求められる（→t430参照）。\n\n**覚え方** 「最低基準を定めた法律＝建築基準法」。下限であって上限ではない。単体規定＝全国・集団規定＝都市計画区域内、という適用エリアの違いもセットで。",
