    exp1: "建築主事とは、建築確認の申請を受け付け審査する地方公共団体の職員（建築基準法4条）。都道府県・市区町村が置く。1999年の法改正で「指定確認検査機関」（民間機関）も建築確認・中間検査・完了検査を行えるようになり、申請先を選択できるようになった。実務上は民間機関への申請が多い。",
    exp2: "「建築主事を置く義務のある団体」が試験で問われる。政令で指定する人口25万人以上の市と都道府県は建築主事を必置（建築基準法4条）。それ以外の市区町村は任意設置。建築主事がいない市区町村の建築確認は都道府県の建築主事または指定確認検査機関が行う。1999年の建築基準法改正で指定確認検査機関（民間機関）への申請が解禁され、現在の実務では民間機関経由の申請が全体の9割超を占める。建築主事の審査期間は木造2階建て以下等の4号建築物（原則省略制度あり）と特殊建築物・3階建て以上等（審査厳格化）で異なる。",
    exp3: "建築主事（→t427参照）と特定行政庁（→t428参照）は異なる概念。建築主事は「審査をする職員（資格を持つ技術職員）」。特定行政庁は「建築主事を置く地方公共団体の長（知事・市長等）」で許可権限を持つ。この2つの混同が典型的なひっかけ。建築確認を行うのは建築主事または指定確認検査機関であり、特定行政庁は許可（接道義務の例外等）と監督（是正命令・使用禁止等）を担う。\n\n**覚え方** 「確認審査をする人＝建築主事（地方公共団体職員）」。長（知事・市長）は特定行政庁。確認は主事・許可は長、という役割分担を覚える。",
