    exp1: "特定行政庁とは、建築主事を置く地方公共団体（都道府県・市区町村）の長（知事・市長等）のこと（建築基準法2条35号）。建築確認の許可・不許可ではなく、建築基準法上の「許可」権限（接道義務の例外・用途制限の緩和・日影規制の適用除外等）を持つのが特定行政庁。",
    exp2: "「許可と確認の違い」が試験のポイント。建築確認は「基準に適合しているか確認する行為（法規制の適用確認・適法性チェック）」で確認機関（建築主事・指定機関）が行う。許可は「例外的に認める行為（原則禁止を特定の条件下で解除）」で特定行政庁（長）が行う。両者の主体・性格の違いを明確に区別すること。特定行政庁が行う許可の具体例：①接道義務の例外許可（→t432参照）②用途制限の緩和③日影規制の適用除外④建蔽率の緩和（角地等）⑤容積率の特例許可。いずれも「例外的・個別的に認める行為」であり、一般的な基準適合とは次元が異なる。",
