    exp1: "フリーレントとは、賃貸借契約において入居後一定期間（1〜3ヶ月が一般的）の賃料を貸主が免除する特約。空室対策・入居促進策として活用される。法律上の規制はなく、賃貸借契約の特約として自由に設定できる。免除期間は「無賃料期間」として扱われ、その後通常の賃料が発生する。",
    exp2: "「フリーレントと敷金・報酬の計算」が実務・試験で出題される。フリーレント期間があっても媒介報酬の計算基礎となる「賃料」は通常の（免除前の）賃料が基準となる（国交省告示の報酬計算規定）。フリーレント期間中に契約解除した場合の違約金（免除賃料相当額の返還義務）特約も有効とされることが多い。敷金の計算基礎も通常賃料を基準とするため「フリーレント中は敷金も0円」というわけではない。フリーレント期間の長さは通常1〜3ヶ月だが、長期フリーレント（6ヶ月超等）の場合は解約制限特約とセットになることが多い。",
    exp3: "不動産広告でフリーレントを表示する場合は景品表示法（優良誤認・有利誤認）に注意。「賃料0円！」と大きく表示してフリーレント期間が極めて短い場合は問題となりうる。宅建業法（→t480参照）の広告規制では「虚偽・誇大広告の禁止」が課されており、フリーレント期間を実際より長く表示することは違反。重要事項説明（→t464参照）でもフリーレントの条件と期間満了後の通常賃料を説明する義務がある。\n\n**覚え方** 「無料期間で借主を引き込む作戦＝フリーレント」。賃料だけ免除・敷金は通常賃料基準・報酬計算も通常賃料で計算という3点セット。",
