    q: "次の状況に当てはまるのは？",
    choices: [{"text":"タバコの焦げ跡・落書き・ペットの傷は借主の故意・過失による損耗であり、借主が修繕費を負担する","correct":true},{"text":"建物の損傷はすべて経年変化として貸主が負担しなければならない","correct":false,"hint":"故意・過失・善良な管理者の注意義務違反による損耗は借主負担。"}],
    exp1: "原状回復とは、賃貸借終了時に借主が借りた物件を「借りた当初の状態（ただし通常損耗・経年変化を除く）」に戻す義務。国土交通省の「原状回復をめぐるトラブルとガイドライン」が標準的な解釈を示す。借主負担の例：タバコのヤニ・落書き・ペット傷・故意の損傷。貸主負担の例：日焼け・通常の画鋲穴・経年劣化。",
    exp2: "「特約による借主負担拡大の有効性」が試験で問われる。通常損耗についても借主に負担させる特約は、①特約の必要性がある②借主が通常の損耗補修費用を負担すると認識している③借主の受ける不利益の内容が明確、という3要件を満たす場合に有効とされる（最高裁平成17年12月16日判決）。ただし消費者契約法10条の不当条項として無効となるケースもある。敷引き（→t436参照）と異なり、通常損耗補修特約は「何が対象になるか不明確」な場合に無効になりやすい。",
    exp3: "「原状回復＝新品に戻すこと」は誤解。経年変化（→t440参照）・通常損耗（→t439参照）を差し引いた「借主の故意・過失による損耗分だけ」を回復するのが原則。クロスは耐用年数6年（税務上）で残存価値がほぼゼロになるという考え方（国交省ガイドライン）により、6年居住後のクロス張替え費用は仮に故意で傷つけても新品代金は請求できず「残存価値分（数円〜）のみ請求可能」となる。\n\n**覚え方** 「借主の不注意・わざとの傷は借主負担、自然に傷むのは貸主負担」。故意過失がキーワード。クロス6年で残存価値ゼロ→借主負担ほぼゼロ、という年数計算も実務・試験で使う。",
