    exp1: "経年変化とは、時間の経過とともに自然に生じる建物・設備の劣化・変色等をいう。日焼けによる壁紙・畳の変色、建具の自然な歪み、設備の経年劣化等が該当する。これらは賃料に含まれるコストとして貸主が負担するのが原則（国土交通省ガイドライン）。",
    exp2: "「耐用年数と残存価値」の考え方が試験で問われる。クロス（壁紙）の耐用年数は6年（税法上）で、6年経過後の残存価値はほぼゼロ（残存価値1円）とする考え方が一般的（国交省ガイドライン）。借主の故意・過失で損傷した場合でも、経年変化を考慮した「残存価値分」のみ請求できる（全額新品交換費は請求不可）。計算例：入居3年のクロスが借主の過失で損傷した場合、新品張替え費用12万円×（6年-3年経過）/6年＝6万円が借主の最大負担額（ガイドラインの考え方）。フローリングは耐用年数20〜30年・設備（エアコン等）は機種により8〜15年が目安。",
    exp3: "経年変化と通常損耗（→t439参照）は連続的な概念で厳密に区別できないことも多い。試験では「時間経過で自然に起こる変化＝貸主負担」「借主の行為（故意・過失）による変化＝借主負担」という軸で判断する。長期入居者（5〜10年以上）は経年変化・通常損耗の範囲が広くなるため、実際の退去時には「借主の実質的な負担はほぼゼロ」になる場合も多い。\n\n**覚え方** 「年を重ねて自然に劣化するのは貸主もち＝経年変化」。時間の分は家賃で払い済み。クロス6年で残存価値ゼロ、入居年数が長いほど借主の実質負担は減る。",
