    scenario: "不動産仲介業者として独立開業した自分が、免許証番号を名刺に刷り込んだ。「大臣(2)第〇〇〇〇号」と書いてある会社の名刺を見て、「この(2)はどういう意味か」と取引先に聞かれた。",
    q: "次の状況に当てはまるのは？",
    choices: [{"text":"免許証番号の括弧内の数字は免許の更新回数を表す","correct":true},{"text":"括弧内の数字は営業所の数を表す","correct":false,"hint":"営業所数とは無関係。あくまで更新回数。"}],
    exp1: "宅建業の免許証番号には「大臣(2)第〇〇〇号」のように括弧書きの数字が付く。この数字は免許の更新回数を示し、新規取得時は(1)、1回更新で(2)となる。更新回数が多いほど業歴が長いことを示す指標ともなる。",
    exp2: "試験では「免許証番号の括弧内の数字の意味」として出題される。「営業所数」「従業員数」「免許年数（営業年数）」と混同させるひっかけに注意。正解は「更新回数」のみ。免許番号の読み方：「国土交通大臣（3）第○○号」→大臣免許（複数都道府県に事務所）で3回更新（取得から最低10年超の業歴）。「○○知事（1）第△△号」→知事免許（1都道府県のみに事務所）で新規取得（更新なし）。免許の有効期間は5年で、更新の申請は有効期間満了の90日前から30日前までの間に行う。",
    exp3: "「(3)は3年営業した証拠」と誤解しやすい。免許の有効期間は5年なので(3)は更新2回済み・新規から最低10年超の業歴を意味する（新規(1)→1回目更新(2)→2回目更新(3)）。また大臣免許と知事免許の使い分け：複数の都道府県に事務所→大臣免許（国土交通大臣）・1都道府県のみ→知事免許（→t456参照）。\n\n**覚え方**\n「括弧の数字はリピート回数（更新回数）」。新規は1回目（初めまして）＝(1)。5年×更新回数で最低業歴を計算（(3)なら最低10年以上）。",
