    exp1: "宅建業者は、免許取得後・営業開始前に、主たる事務所（本店）につき1,000万円、従たる事務所（支店等）1か所につき500万円の営業保証金を供託所に供託しなければならない。供託先は主たる事務所の最寄りの供託所。",
    exp2: "「本店1,000万円・支店500万円」は頻出の数値。本店＋支店2か所なら1,000万円＋500万円×2＝2,000万円となる。保証協会（→t457参照）加入の場合は弁済業務保証金分担金（本店60万円・支店30万円）に大幅軽減される。保証協会加入で本店＋支店2か所：60万円＋30万円×2＝120万円（通常の6分の1以下に軽減）。営業保証金の供託後・免許取得後に「供託しました」と免許権者に届出をしなければ営業開始できない（供託→届出→営業開始の順序）。",
