    exp1: "従たる事務所（支店）1か所ごとに、宅建業に従事する者の5人に1人以上の割合で専任の宅建士を設置しなければならない（宅建業法15条）。また、営業保証金は従たる事務所1か所あたり500万円を主たる事務所の最寄り供託所に供託する。",
