    exp1: "事務禁止処分は、宅建士が宅建業法違反等の一定の行為をした場合に都道府県知事が課す行政処分で、最長1年間宅建士の事務（重要事項説明・記名等）が禁止される。処分中も登録自体は消えない。処分期間中は宅建士証を都道府県知事に提出しなければならない。",
    exp2: "「事務禁止処分中の宅建士証の扱い」が試験に出る。処分を受けた者は「速やかに」宅建士証を都道府県知事に「提出」する義務がある（→t462参照：返納ではない）。提出しないと30万円以下の罰金の対象となる。処分期間が終了した後は、提出した宅建士証が返還される（処分期間終了まで知事が保管）。事務禁止処分は都道府県知事が行うが、違反行為が複数の都道府県にまたがる場合は国土交通大臣が処分権者になる場合もある。事務禁止処分中は宅建士としての事務（重要事項説明・記名等）は一切できないが、勤務先で一般業務（事務補助等）を行うことは禁止されていない。",
    exp3: "「提出（→t462参照）」と「返納」を混同しやすい。事務禁止処分では「提出（後で返還される）」。登録消除・宅建士証の失効時は「返納（返還されない）」。また宅建士証の有効期間は5年で、有効期間満了時に更新（更新申請）が必要。更新をしなかった場合は宅建士証が失効し「返納義務」が生じる。\n\n**覚え方**\n「事務禁止＝預ける（提出・後で返ってくる）」「登録消除・失効＝返す（返納・戻らない）」。預けるか返すかで区別。提出と返納の使い分けは最頻出の試験問題。",
