    q: "次の状況に当てはまるのは？",
    choices: [{"text":"個人業者の死亡の場合、相続人が死亡を知った日から30日以内に届出を行う","correct":true},{"text":"死亡日から30日以内に届出を行えばよい","correct":false,"hint":"起算点は「相続人が死亡を知った日」であり、死亡日ではない。"}],
    exp1: "宅建業者が死亡した場合、その相続人は「死亡を知った日から30日以内」に免許権者（知事または大臣）へ届出を行わなければならない。法人が解散・廃業の場合は清算人・代表役員等が廃業等を知った日から30日以内に届出する。届出があった時点で免許は失効する。",
    exp2: "届出期限「30日以内」と起算点「知った日から」のセットが試験の核心。「死亡日から30日」「廃業決定日から30日」という誤りが選択肢に出やすい。届出事由と義務者の一覧：①死亡→相続人②合併による消滅→消滅会社の代表役員③破産→破産管財人④解散（合併・破産以外）→清算人⑤廃業→本人（個人）または代表役員（法人）。いずれも「知った日から30日以内」が起算点。届出があった日に免許が失効する（遡って失効日は届出日）。",
