    choices: [{"text":"取引関係者から請求を受けた場合は従業者証明書を提示しなければならない","correct":true},{"text":"従業者証明書は宅建士のみが携帯する義務がある","correct":false,"hint":"宅建士であるかどうかにかかわらず、宅建業者の従業者全員が携帯義務を負う。"}],
    exp1: "宅建業者は、その従業者（宅建士・一般従業員問わず）に従業者証明書を携帯させなければならず、従業者は取引関係者から請求を受けた場合にこれを提示しなければならない（宅建業法48条）。証明書は宅建業者が発行するもので、氏名・有効期間・従事する宅建業者の商号等が記載される。",
    exp2: "「宅建士証（→t461参照）」と「従業者証明書」の違いが試験で問われる。宅建士証は個人が都道府県知事から交付を受けるもの（5年有効）、従業者証明書は宅建業者が交付する社内証明書（有効期間は業者が設定）。両方を混同させるひっかけが多い。従業者証明書の必要的記載事項：①氏名②生年月日③商号・名称④法人の場合は代表者の氏名⑤従業者の種別（宅建士か否か）⑥有効期間⑦証明書番号。宅建業者は従業者名簿（従業者証明書の発行記録を含む）を事務所ごとに備え付ける義務がある。",
    exp3: "「従業者証明書は宅建士だけが持つ」という誤りは頻出。非宅建士の一般スタッフも携帯義務がある点を必ず覚える。また従業者証明書の携帯義務は「宅建業に関する業務を行う場合」に限られるため、社内の総務・経理担当など取引業務に関与しない従業員には適用されない場合がある。違反（従業者証明書を携帯させていない場合）は宅建業者への罰則（30万円以下の罰金）対象。\n\n**覚え方**\n「従業者証明書＝会社が作る・全員携帯」「宅建士証＝県（知事）が作る・宅建士だけ」。作成主体で区別。取引関係者から求められたら提示義務（→t461参照と同じルール）もある。",
