    keyword: "買主・借主に説明・売主には不要",
    scenario: "土地売買の仲介をしている不動産営業マンの自分が、売主・買主双方から依頼を受けた（双方代理に近い状況）。「重要事項説明書は売主にも渡すべきか」と先輩に聞いたところ、「原則は買主だけでいい」と言われた。",
