    exp1: "重要事項の説明（宅建業法35条）は、宅建業者が取引の「相手方」に対して行う義務がある。売買では買主、賃貸では借主がその対象。売主・貸主は説明を受ける側ではない。ただし業者間取引（双方が宅建業者）では重要事項説明書の交付は必要だが説明は省略できる場合がある。",
    exp2: "「説明義務の相手方は誰か」が出題の核心。売主・貸主への説明は法的義務ではない。業者間取引での省略可否については「書面（35条書面）の交付義務は省略不可・口頭説明は省略可」という整理が試験で問われる。2022年改正で業者間取引でも35条書面の電磁的交付（→t486参照）が解禁されたが、書面（または電磁的方法による提供）自体の交付義務は業者間でも残る。説明相手の注意点：買主・借主への説明が義務だが、買主・借主が「宅建業者自身」の場合は口頭説明を省略できる（書面交付は必要）。",
    exp3: "「業者間取引では説明不要」と単純化しすぎないこと。書面（35条書面）の交付義務は業者間でも残る。口頭説明（宅建士による説明行為）が省略できるだけ。また説明を行う宅建士は「専任・非専任を問わず」「有効な宅建士証を持つ者」であれば誰でもよい（→t466参照）が、IT重説（→t465参照）の場合は映像・音声で顔出しが必要。\n\n**覚え方**\n「35条説明は買主（借主）へのプレゼント。売主（貸主）には渡さなくていい」。業者間取引でも書面交付は必要、口頭説明のみが省略可。",
