    scenario: "地方在住の購入者とオンラインで重要事項説明を行いたい不動産営業マンの自分。「IT重説は誰でも受けられるのか」「何か事前準備が必要か」と上司に確認した。",
    q: "次の状況に当てはまるのは？",
    choices: [{"text":"IT重説はテレビ会議等双方向通信システムを使用し、事前に相手方が書面等を受け取っていることが条件","correct":true},{"text":"IT重説は録画した動画を相手方に送付する方法でも実施できる","correct":false,"hint":"録画配信は「双方向通信」ではなく不可。リアルタイムの双方向通信が必須。"}],
    exp1: "IT重説（情報通信の技術を利用した重要事項説明）は、テレビ会議システム等の双方向通信手段を使って重要事項説明を行う方法。実施条件として、①相手方が事前に重要事項説明書等を受け取っていること、②映像・音声の双方向リアルタイム通信であること、③宅建士証を画面で確認できることが必要。",
    exp2: "「IT重説の条件」として試験で出やすいのは「事前に書面（または電磁的方法）受領済み」「双方向リアルタイム通信」「宅建士証の画面での確認」の3点。録画・一方向配信・電話のみは不可。2022年の宅建業法改正（→t486・t487参照）でIT重説が本格解禁され、賃貸・売買ともに対象（非対面での重説が標準化）。IT重説の実施手順：①事前に35条書面（または電磁的方法で提供）を相手方が受領②テレビ会議等で映像・音声確認③宅建士証を画面に掲示して相手方が確認④重要事項説明を実施⑤相手方が内容を理解したことを確認。",
    exp3: "「電話での重説」はIT重説の要件を満たさない（映像なしのため）。映像（顔が見える）＋音声の双方向性が必須。また「映像が途切れた場合」の対応も実務上問われる（映像を回復させるか、対面での重説に切り替えるかを判断する義務がある）。相手方が「通信環境の確認ができている」ことも暗黙の前提要件として理解しておく。\n\n**覚え方**\n「IT重説＝ビデオ通話で対面と同じ体験」。事前書面受領・双方向映像・宅建士証の顔出し確認の3条件を確保。電話のみはNG・録画はNG。",
