    exp1: "35条書面（重要事項説明書）への記名は、その取引に関与した宅建士が行えばよい（宅建業法35条）。必ずしも重要事項説明を実施した宅建士と同一人物でなくてよい。ただし記名する宅建士は専任・非専任を問わず、有効な宅建士証を持つ者であることが必要。",
    exp2: "「記名する宅建士と説明する宅建士は同一でなくてよい」というルールが試験で出る。「説明した宅建士しか記名できない」は誤り。取引関与が条件（その取引に何らかの形で関わった宅建士であればよい）。なお複数の宅建業者が共同で媒介する場合（共同媒介）、各業者がそれぞれ35条書面に記名することが原則。また専任宅建士の記名が必要とは定められておらず、非専任宅建士が記名することも可能（ただし宅建士証が有効であること）。",
    exp3: "37条書面（→t467参照）の記名も同様に取引に関与した宅建士が行えばよい。35条・37条ともに「説明担当者限定」ではない点を押さえる。電磁的方法で35条書面を提供する場合（→t486参照）も「宅建士の記名（電子署名等）」は維持される。「電磁的交付なら記名不要」という誤りに注意。\n\n**覚え方**\n「書面の記名＝取引に関わった宅建士ならOK。説明した人でなくてもよい」。専任・非専任問わず有効な宅建士証を持つ者が記名可。",
