    exp1: "37条書面の必要的記載事項には、売買代金以外の金銭の授受に関する事項（額・授受の時期・目的）が含まれる（宅建業法37条1項4号）。手付金・保証金・固定資産税清算金・管理費精算金など、売買代金以外に当事者間で授受される金銭はすべてここで明示する必要がある。",
    exp2: "37条書面の記載事項は「必要的記載事項（必ず記載）」と「任意記載事項（定めがある場合のみ）」に分かれる（→t467参照）。売買代金以外の金銭（手付金・保証金・固定資産税清算金・管理費精算金等）の授受がある場合はその額・授受の時期・目的が必要的記載事項。「定めがある場合のみ記載」という誤りが選択肢に出やすい。金銭授受の記載漏れは宅建業者への行政指導・最悪の場合処分の対象となる。固定資産税・管理費の日割り清算金も「売買代金以外の金銭」として記載対象。",
    exp3: "「手付金は重要事項（35条）で説明し、37条には書かなくていい」という誤りが多い。35条（→t464参照）でも37条でも、それぞれの場面で記載・説明が必要（手付金は35条では説明対象・37条では必要的記載事項）。手付金保全措置（業者が売主の場合は代金の5%超または1,000万円超の手付金について保全義務あり）との関係も整理しておく。\n\n**覚え方**\n「お金の授受は必ず37条書面に書く。代金以外（手付金・固都税清算金・管理費清算金）も同じルール」。35条説明と37条記載のダブル義務があると覚える。",
