    keyword: "35条書面・用途地域・建蔽率・容積率等の記載",
    scenario: "中古一戸建てを購入しようとしているマイホーム検討中の30代会社員の自分が、受け取った重要事項説明書を見ると「第1種低層住居専用地域・建蔽率60%・容積率150%」と書いてあった。「これって何のために書いてあるの？」と不動産会社に聞いた。",
    q: "次の状況に当てはまるのは？",
