    exp1: "35条書面には、飲用水・電気・ガスの供給施設および排水施設の整備状況（整備されていない場合は整備の見通しとその負担に関する事項）を記載する義務がある（宅建業法35条1項4号）。特に未整備地域・開発区域では「整備時期・費用負担者」まで説明することが求められる。",
    exp2: "「整備済みの場合」と「未整備の場合」で記載内容が異なる点が試験に出る。整備済み：現状の整備状況の記載。未整備：「整備の見通し」と「整備費用の負担者・負担額」まで説明義務がある。特に新興住宅地・開発中の土地では上下水道・都市ガスが未整備のケースが多く、引込み工事費用（数十万〜数百万円）が別途必要になる場合がある。排水施設（下水道・浄化槽・汲み取り等）の種別も説明対象で、浄化槽の場合は定期清掃費用が発生する点も伝える必要がある。",
    exp3: "「ガスはプロパン（LP）か都市ガスか」の違いは月々のガス料金に大きく影響するため（プロパンは都市ガスの約2倍程度が相場）、重要事項として説明すべき情報。都市ガスと混同させたひっかけに注意。また「電気容量（アンペア数）」や「オール電化かどうか」も生活費に影響する情報として実務上説明されることが多い（法定説明義務の有無は要確認）。\n\n**覚え方**\n「水（飲料水・排水）・電気・ガス（都市ガスorプロパン）＝生活の3本柱。整備状況は必ず35条書面に入れる」。未整備なら見通し・費用負担まで説明。",
